        /* ⬆️ 新版羁绊专属排版 ⬆️ */

        .foot {
            margin-top: 50px;
            padding-top: 30px;
            border-top: 1px solid var(--border-gold);
            display: flex;
            gap: 20px;
        }

        .btn {
