        /* =========================================
           [大乘期·神识探查弹窗]
        ========================================= */
        .sys-modal {
            position: fixed;
            inset: 0;
            background: rgba(50, 30, 10, 0.7);
            backdrop-filter: blur(5px);
            -webkit-backdrop-filter: blur(5px);
            z-index: 2000;
            display: flex;
            justify-content: center;
            align-items: center;
        }

        .sys-modal-content {
            width: 90vw;
            max-width: 600px;
            background: var(--paper-base);
            border: 2px solid var(--accent-red);
            box-shadow: 0 20px 50px rgba(90, 70, 40, 0.5);
            clip-path: polygon(0 2%, 100% 0, 100% 98%, 0 100%);
            display: flex;
            flex-direction: column;
        }

        .sys-modal-header {
            padding: 20px;
            border-bottom: 1px dashed var(--border-gold);
            display: flex;
            justify-content: space-between;
            align-items: center;
        }

        .sys-modal-title {
            font-family: var(--f-art);
            color: var(--accent-red);
            font-size: 1.5em;
            letter-spacing: 2px;
            font-weight: bold;
        }

        .sys-modal-close {
            color: var(--accent-gold);
            font-size: 1.5em;
            cursor: pointer;
            transition: 0.3s;
            font-family: var(--f-body);
        }

        .sys-modal-close:hover {
