                            "天机阁奴隶拍卖行烙下耻辱编号的滚烫玄铁锁骨环",
                            "沾着口水和黑泥的半块凡间糖画 (你唯一关于甜的回忆)",
                            "封印着人类父亲一缕内疚残魂的黯淡玉佩",
                            "青丘狐妖母亲遗留的早已失去灵气的残破魅惑香囊",
                            "刺入脊椎的一根用来定期抽取半妖骨髓的空心毒针",
                            "一本被撕得粉碎只剩封面的笑话书《人妖两族和平盟约》",
                            "刻着太古妖文与人族符箓相互倾轧排斥的废弃镇压灵符",
                            "合欢魔宗用来催情致幻的残缺炉鼎合欢镣铐",
                            "用百家布拼接而成的百衲衣 (缝满了不同半妖逃亡者的血泪)",
                            "一颗用来压制野性理智的冰寒刺骨的菩提佛珠"
                        ],
                        D: [
                            "竖瞳凄美而诡异，给人一种强烈的破碎感，总是习惯性地低着头。",
                            "卑微隐忍，满身鞭痕，为了生存可以不择手段，像阴沟里的老鼠。",
                            "戴着厚厚的破帽子试图遮住兽耳，眼神总是像惊弓之鸟般躲躲闪闪。",
                            "半边脸是绝世容颜，另半边脸却覆盖着狰狞粗糙的鳞片，半魔半仙。",
                            "拥有一条毛茸茸的尾巴，虽然很可爱，但却拼命将其藏在破烂的裤管里。",
                            "身体总是控制不住地颤抖，散发着好闻却致命的异香。",
                            "平时看着像文弱的人类，一旦发怒就会长出獠牙和利爪，彻底失去理智。",
                            "脖子上带着无法取下的项圈，那是奴隶的证明，勒入血肉。",
                            "背上长着畸形的不对称翅膀，无法飞行，只能成为被同类嘲笑的累赘。",
                            "双手完全是锋利的兽爪，无法做精细的活，只能用来无情杀戮。",
                            "皮肤上东一块西一块地长满了杂乱的羽毛，看起来像个怪物。",
                            "脸上带着疯狂与绝望的笑意，嘴角总是裂到耳根。",
                            "总是蜷缩在阴暗的角落里，像野兽一样警惕着四周的一切风吹草动。",
                            "瞳孔是极其不协调的一蓝一红，眼神中永远透着对整个修真界的防备与恨意。",
                            "左半身如玉树临风的仙家少侠，右半身却覆盖着粗糙的妖兽角质，如神魔缝合体。",
                            "脖颈处布满被奴役项圈勒得深可见骨的陈年老疤，声音沙哑得像生锈的砂纸。",
                            "嘴角带着自嘲的惨笑，下意识地想把头上那对毛茸茸的残缺兽耳藏进斗篷里。",
                            "脊背佝偻，仿佛常年承受着毒打，十指指甲尖锐如弯钩且缝隙里满是黑泥。",
                            "皮肤苍白得几近透明，隐约可见皮下青紫色的狂暴妖脉如小蛇般可怖地蠕动。",
                            "脸上被人用滚烫的烙铁烫下了一个“贱”字，眼神麻木空洞，仿佛失去了所有痛觉。",
                            "头发是驳杂不堪的枯黄与雪白相间，就像一丛杂草，偶尔抖落出几片细碎的残鳞。",
                            "笑起来的时候，嘴里会控制不住地露出锋利交错的妖兽獠牙，显得既可悲又狰狞。",
                            "走路时一瘸一拐，右腿显然是被人打断后粗暴地接上了一段完全不匹配的妖骨。",
                            "身上散发着混合了下水道腐臭与妖血腥味的难闻气息，走到哪里都会招来嫌恶的目光。",
                            "用一层又一层脏绷带死死缠住右手，因为那只手完全是覆盖着青鳞的妖魔巨爪。",
                            "眼神清澈得像个孩子，但身体却因为两股血脉的常年冲突而瘦弱得像个随时会碎掉的瓷娃娃。",
                            "长着一副极具欺骗性的天真面孔，但指缝间暗藏的妖毒说明了他在底层的血腥生存法则。",
                            "因为曾作为实验体被浸泡在毒液中，全身皮肤呈现出诡异的淡紫色，连眼白都被染黑。"
                        ],
                        C: [
                            /* --- T1 引气·微末挣扎（8位，半妖大限50岁）--- */
                            { n: "阿呆", t: "半妖奴隶", d: "奴隶黑市里的半妖少女，15岁。脑子不太灵光但心地纯善。常替同笼的幼小半妖挨鞭子，事后还会强忍着泪水傻笑安抚同伴，在暗无天日的黑市中如同一株可悲的杂草。(T1)" },
                            { n: "猫儿", t: "半猫小偷", d: "身手敏捷的半猫少女，14岁。黑色短发，一双琥珀色猫眼。为了给患血脉崩溃症的弟弟买药，常在黑市铤而走险偷窃，被抓住了就龇牙装凶，但手抖得连脖子上的铃铛都在响。(T1)" },
                            { n: "泥鳅", t: "半鳅孤儿", d: "半鳅半人的流浪儿，12岁。皮肤滑腻手指间有薄蹼。常年在码头淤泥里摸鱼虾果腹，曾因凡人船夫施舍的一碗热粥记恩十年，每年都会在码头暗处留下一串晒干的河鱼报恩。(T1)" },
                            { n: "小草", t: "半草弃婴", d: "半草半人的女婴，3岁。因妖气显露被凡人父母遗弃在路边。生命力顽强到断枝也能自行接回，全凭体内那点微薄的草木灵气苟活于世。(T1)" },
                            { n: "小蜗", t: "半蜗乞儿", d: "半蜗半人的流浪女童，8岁。背着一个比例失调的小壳，行动比常人慢半拍。壳中是她全部家当：三枚废铜钱、一颗化掉的糖、和一张亡母留下的遗书。(T1)" },
                            { n: "狗剩", t: "凡人乞儿", d: "黑市里的凡人小乞丐，10岁（凡人寿元基准）。曾因为偷半块馒头被商户打残，临死前将染血的馒头塞给身边的半妖，嘶哑地留下了一句“一定要活下去”的遗言。(T1)" },
                            { n: "笼中妖", t: "断腿老妖", d: "奴隶黑市里沦为观赏物的残废纯血老妖，280岁（妖族基准）。虽然每天痛骂周围的半妖血脉肮脏，却在夜深人静时，偷偷隔着铁栏杆教导年轻混血如何吐纳妖气压制伤痛。(T1)" },
                            { n: "小蝶", t: "试药哑女", d: "无间魔宗试药棚里的半妖女孩，16岁。在服下某种剧毒魔药导致血脉彻底崩溃、浑身化作血水前，拼尽全力用带血的手指在地上给身后的同伴画了个“逃”字。(T1)" },

                            /* --- T2 炼体·底层挣扎（8位，半妖大限60岁）--- */
                            { n: "铁柱", t: "半牛苦力", d: "力大无穷的半牛人少女，18岁。身材魁梧头上两只短角。在码头扛包被工头克扣工钱也从不反抗，只想在血脉崩溃前攒够灵石，给生病的母亲赎身买药。(T2)" },
                            { n: "鲛人泪", t: "半鲛歌姬", d: "被卖到青楼的半鲛人，22岁。海藻般的长发遮住半张被毁的脸。歌声能致幻，但受血脉排斥影响每次唱歌都会泣血，为了生存却不敢停下。(T2)" },
                            { n: "鼠儿", t: "半鼠密探", d: "半鼠半人的地下情报贩子，15岁。尖嘴鼠须，常年在地下黑市的垃圾堆里翻找生存物资。她熟悉每一条暗道和每一个不能惹的老怪，靠贩卖低阶情报苟活。(T2)" },
                            { n: "雀斑", t: "半雀信使", d: "半雀半人的女信使，17岁。满脸雀斑，双臂覆着褐色羽毛。因翅膀畸形飞不高但跑得极快，以替人送信为生，恪守从不拆信的底层规矩。(T2)" },
                            { n: "蛛儿", t: "半蛛织工", d: "半蛛半人的纺织女工，25岁。在城中最大的织坊做苦力，指尖能吐出蕴含微弱灵气的细丝。因每天定额太高，十指常年处于出血、结痂、再出血的循环中。(T2)" },
                            { n: "蚁娘", t: "半蚁搬工", d: "半蚁半人的女搬运工，20岁。身材矮小却力大无穷，能举起自身百倍重量的货物。寡言少语埋头干活，攒下的灵石全寄回了灵气枯竭的半妖村庄。(T2)" },
                            { n: "残刃", t: "死斗炮灰", d: "斗兽场里负责暖场消耗妖兽体力的底层半妖，30岁。满身伤疤没有一块好肉，在一场必死的死斗中替同僚挡下致命一击，临死前笑称这短暂残酷的一生终于解脱。(T2)" },
                            { n: "木头", t: "人肉盾牌", d: "大宗门外围弟子专门雇来在秘境探路的人肉盾牌，28岁。脑子迟钝但防御极高，常被主子无情地推进法阵踩雷，只要一口气还在便憨厚地认死理前行。(T2)" },

                            /* --- T3 筑基·夹缝求生（9位，半妖大限100岁）--- */
                            { n: "狼女", t: "半狼斗士", d: "斗兽场里的连胜冠军，45岁。银灰色短发，脸上三道战痕。野性十足，只听从能正面将其击溃的绝顶强者，一旦彻底折服便会交出绝对的忠诚。(T3)" },
                            { n: "药师", t: "半妖医者", d: "研究半妖血脉的疯狂女医，60岁。拿自己做实验，强行将数种妖骨缝合进体内。在正道大宗眼里她是个疯子，但被她从走火入魔中救回来的半妖却尊她为菩萨。(T3)" },
                            { n: "蝶衣", t: "半蝶舞姬", d: "半蝶半人的舞娘，35岁。一双绚丽的残缺蝶翼是她全部的骄傲。在边陲小镇酒馆跳舞为生，不卖身只卖笑，拼命攒钱只为给基因畸形的妹妹买一颗化形丹。(T3)" },
                            { n: "蜃娘", t: "半蜃艺人", d: "半蜃半人的流浪艺人，80岁。靠吞吐蜃气制造低阶幻境谋生。表面在马戏团嬉皮笑脸，暗地里收留了几十个无家可归的半妖孤儿，是底层的无名英雄。(T3)" },
                            { n: "海藻", t: "半藻散修", d: "半海藻半人的女修，50岁。墨绿长发在水中会发荧光。隐居海边潮汐洞采珠为生，性情温和从不与人争斗，却在一次海啸中以微薄修为护住了整片凡人渔村。(T3)" },
                            { n: "螳姬", t: "半螳猎手", d: "半螳半人的女猎手，40岁。双臂畸形化为一对镰刀状前肢。在十万大山边缘以猎兽为生，坚守从不杀幼崽和怀孕母兽的猎人底线。(T3)" },
                            { n: "蝉女", t: "半蝉隐修", d: "半蝉半人的女隐士，90岁（大限将至）。在地下蛰伏十七年方才熬过血脉冲突破土而出。出关之日便用生命中最后的鸣叫声，震退了围攻半妖村的妖兽。(T3)" },
                            { n: "药罐老李", t: "叛逃匠师", d: "万灵衍化宗叛逃的底层研究员，130岁（人族基准）。满脑子提取妖血的疯狂想法，虽然极度狂热，但在宗门清剿时却破天荒地带走了数名半妖实验品，并未将他们解剖。(T3)" },
                            { n: "黑鸦阿九", t: "无面死士", d: "春秋楼外围的半妖死士，75岁。终生戴着乌鸦面具生活在阴影里。每次执行必死的暗杀任务前，都会默默替同僚打磨兵器并留下无人认领的遗书。(T3)" },

                            /* --- T4 金丹·初露锋芒（10位，半妖大限250岁）--- */
                            { n: "混江龙", t: "半龙水匪", d: "半龙半人的水匪头子，150岁。体表覆着淡青色逆鳞。领着一群半妖在江上劫富济贫，专抢各大宗门欺压底层的商船，抢来的灵石大半分给了沿江的半妖村落。(T4)" },
                            { n: "毒牙", t: "半蛇刺客", d: "半蛇半人的冷血杀手，120岁。蛇瞳竖立指甲含剧毒。接单杀人从不失手，但每年冬至都会隐匿行踪，匿名给中州城里的半妖孤儿院送去一袋上品灵石。(T4)" },
                            { n: "灰羽", t: "半鹰游商", d: "半鹰半人的行脚商人，180岁。双臂化翼，常年往来人族城镇与凶险的半妖村落倒卖货物。杀价不眨眼，但赚取的资源大半都暗中散给了穷困同族。(T4)" },
                            { n: "蝎尾", t: "半蝎护卫", d: "半蝎半人的雇佣护卫，160岁。背后拖着一根致命的剧毒蝎尾。沉默寡言，信奉拿钱办事极重承诺，只要她还有一口气，护送的镖车就绝不会失落。(T4)" },
                            { n: "壁虎", t: "半虎飞贼", d: "半壁虎半人的女飞贼，110岁。手脚带有倒刺吸盘能在禁空法阵中如履平地。专偷大奸大恶之徒，得手后总会留下一张写着“替你还因果”的纸条。(T4)" },
                            { n: "珊瑚", t: "半珊修士", d: "半珊瑚半人的女修，200岁。周身萦绕七彩珊瑚枝，定居海底暗礁培育灵珊。因混血体质极其脆弱，宛如精美的瓷器，触之即碎，极少参与海族争斗。(T4)" },
                            { n: "蛾女", t: "半蛾织娘", d: "半蛾半人的织造女工，190岁。一对触角能敏锐感知法则光谱的变化。她织的月光纱只在满月之夜才能完工，大荒的半妖新娘们哪怕排队三年也只为求得一匹。(T4)" },
                            { n: "鱼娘", t: "半鱼渔娘", d: "半鱼半人的渔家女，140岁。耳后生有一排腮裂可深海呼吸。常年在怒涛峡打鱼，每逢海族风暴过后总能从沉船里捞出修炼物资，养活了整座峡谷的半妖。(T4)" },
                            { n: "断丝青女", t: "霓裳女工", d: "霓裳宗地下采丝厂的半妖女工，130岁。曾因私藏一截天蚕丝被监工残忍斩去双手。在后来的死囚暴动中，她以残臂为同伴挡下了淬满剧毒的致命暗箭。(T4)" },
                            { n: "姬尘", t: "荒古弃子", d: "荒古姬家被赶出家门的半妖私生子，80岁。觉醒了失败的残缺虚空血脉，带着满腔仇恨化身大荒中的绝命杀手，发誓有朝一日要在血脉崩溃前杀回中州本家。(T4)" },

                            /* --- T5 元婴·名动一方（9位，半妖大限500岁）--- */
                            { n: "涂山弃徒", t: "半狐叛将", d: "因血脉不纯被青丘驱逐的半狐，350岁。九尾只修出畸形的六尾。曾立下血誓要报复纯血狐族，但在屠刀举起时却始终下不去死手，内心充满了对归属的扭曲渴望。(T5)" },
                            { n: "影", t: "皇室死士", d: "大虞皇室从小豢养的半妖死士，280岁。没有感情，容貌被特殊药水刻意抹除。一生绝对服从敕令，却在某次刺杀任务中破天荒地放走了一对半妖母子，连她自己都不知为何。(T5)" },
                            { n: "红莲", t: "起义首领", d: "半妖地下起义军女首领，450岁。掌握着狂暴的红莲业火。誓要推翻纯血压迫建立半妖国度，面对正道高高在上的招安，她只冷冷反问对方是否先放下了屠刀。(T5)" },
                            { n: "白榆", t: "半鹿药师", d: "半鹿半人的游方女医，320岁。头顶一对晶莹鹿角背着药篓走遍大荒。诊金极其随意，有时一枚铜板有时一碗粥，漫长岁月里救过的底层半妖比大宗门里的弟子还多。(T5)" },
                            { n: "蹄音", t: "半马信使", d: "半马半人的极速信使，260岁。化形后下半身是强悍的马躯，日行万里无视地形。修真界最守规矩的信鸽，从不拆信，只在每年除夕给自己放一天假。(T5)" },
                            { n: "豹胆", t: "半豹女将", d: "半豹半人的雇佣兵团长，410岁。全身覆盖豹纹短打，手持残破双刀。带领着一支纯半妖组成的敢死佣兵团，专接各大宗门不愿碰的最危险悬赏，死亡率极高。(T5)" },
                            { n: "蜜娘", t: "半蜂养蜂人", d: "半蜂半人的养蜂女修，380岁。身后一对透明薄翼。她豢养的灵蜂群能无视瘴气授粉万里，整个南荒边缘的半妖药田都靠她的蜂群勉强续命。(T5)" },
                            { n: "鹤唳", t: "半鹤剑修", d: "半鹤半人的独臂女剑修，490岁（大限将至）。曾隐瞒血脉拜入昆仑学剑，暴露后被废去一臂逐出师门。她虽流落大荒，其孤绝的剑法仍在昆仑外门弟子中被偷偷模仿。(T5)" },
                            { n: "极夜盲主", t: "黑市眼线", d: "天机阁黑市隐秘的半妖鉴定师，499岁（血脉濒临崩溃）。双眼被毒瞎蒙着黑布，对各大势力的黑料了如指掌，总能给走投无路的通缉犯指出一条最凶险的亡命活路。(T5)" },

                            /* --- T6 化神·半妖栋梁（10位，熬过生死关，血脉交融寿命重塑至3000岁）--- */
                            { n: "鬼手", t: "半妖盗圣", d: "半人半妖的大盗，1200岁。长着三只手，精通空间法则。号称盗圣，曾成功潜入万法阁藏经阁，将高阶秘籍复印无数份，免费散发给买不起功法的半妖散修。(T6)" },
                            { n: "青萝", t: "半螭水君", d: "半螭半人的江湖散修，1800岁。能御水行舟。船钱随缘，但在渡口立下三不渡的铁律：纯血妖族不渡、欺压半妖者不渡、身背无辜杀业者不渡。(T6)" },
                            { n: "绣娘", t: "半蛛织女", d: "半人半蛛的织造大师，2100岁。下半身保留着巨型蛛体，吐出的本命丝比精金还韧。隐居深山孤僻寡言，若遇到真心欣赏其手艺的知音，会慷慨赠送地阶法衣。(T6)" },
                            { n: "冰鳞", t: "半蛟龙君", d: "半蛟半人的散修大能，1500岁。体表覆着抗魔冰蓝鳞片。坐拥北荒一条绵延万里的极寒冰河，河中一切低阶水妖皆尊她为无冕之王。(T6)" },
                            { n: "焰骨", t: "半凤女修", d: "凤凰与凡人的禁忌之女，2800岁。体内流淌着极度不稳定、稀薄的涅槃之火。被高傲的凤凰一族视为奇耻大辱，独自在大荒深处对抗着随时可能自焚的宿命。(T6)" },
                            { n: "蛛后", t: "地下城主", d: "半人半蛛的地下城主，2500岁。在深渊裂缝的绝地中建立了一座巨大的半妖庇护所。接纳一切被大荒万族遗弃、通缉的混血儿，被尊称为“蛛母”。(T6)" },
                            { n: "雾姬", t: "半蜃幻术师", d: "半蜃半人的幻术大师，2900岁。一口本命蜃气能瞬间笼罩整座大型城池。她立誓不用幻术谋杀生灵，只在战场上造出令人神魂绝望的修罗幻象以劝退敌军。(T6)" },
                            { n: "银鬃", t: "半狮女帅", d: "半狮半人的万妖盟女帅，2200岁。一头银色鬃毛威风凛凛，掌握极致的庚金法则。领兵打仗从不落败，是妖族大军中唯一一位令纯血妖王也必须低头的半妖将领。(T6)" },
                            { n: "引渡使白灵", t: "云梦星舟", d: "云梦泽外派大荒的接引使，1600岁。常年撑着一艘能隐匿于星光法则中的小舟，在大荒险地四处搜寻被正魔两道通缉追杀的半妖，将其接回梦幻乡。(T6)" },
                            { n: "血鼎苏奴", t: "合欢鼎炉", d: "合欢魔宗最底层地窖圈养的极品半妖炉鼎，1900岁。忍辱负重百年，暗中逆向推演出了破解采补之术的残缺功法，蛰伏于黑暗中静待着能将魔宗覆灭的倾覆之机。(T6)" },

                            /* --- T7 合体·半妖霸主（9位，大限8000岁）--- */
                            { n: "蛮", t: "无枷武圣", d: "战皇殿叛徒，5000岁。以高阶纯血大妖精血为食的“无枷者”。肉身成圣的混血战神，打破了半妖体魄的极限，一生只敬仰真正的力量，蔑视一切血统论。(T7)" },
                            { n: "珊瑚王", t: "半珊海主", d: "半珊瑚半人的海底女王，6500岁。身躯已与整片庞大的海底珊瑚礁融为一体。庇护着上万名无家可归的海洋半妖，任何来犯的大军都会被珊瑚林绞杀于无声中。(T7)" },
                            { n: "枯荣", t: "半树半人", d: "半树半人的活化石，7800岁。身躯已与一棵万年太古神树彻底融合。根系绵延百里地脉，每一片飘落的树叶都能化作她的耳目，从不错过辖区内任何半妖的求救。(T7)" },
                            { n: "星羽", t: "半鹏天空主", d: "半鹏半人的天空之主，4200岁。双翼一展足以遮天蔽日。凭借合体期伟力在九霄云海中构筑了一座隐秘的浮空城，专门收留那些遭到人类猎杀的飞禽类半妖。(T7)" },
                            { n: "血蔷薇", t: "半蝠领主", d: "半蝠半人的血族女领主，5800岁。以纯血妖王鲜血为食，立下铁律从不对半妖同胞下手。她的阴森古堡是大荒半妖的绝对庇护所，白天闭门谢客，夜晚灯火通明。(T7)" },
                            { n: "无垢", t: "混沌半妖", d: "万族混血的奇异存在，6200岁。体内融合了数十种狂暴血脉却奇迹般地达到了完美平衡。被各大纯血道统疯狂排斥，却也因其诡异莫测的法则力量而无人敢惹。(T7)" },
                            { n: "千鳞", t: "半龙半蛇", d: "龙蛇混血的半妖老祖，7100岁。身披坚不可摧的千鳞战甲，隐居东海雾海深处不问世事。但若有半妖群落惨遭屠戮，她那带有极致毒素的浓雾会蔓延千里遮蔽凶手营地。(T7)" },
                            { n: "堪舆天工公输瑾", t: "半妖大匠", d: "堪舆九玄局的首席大匠师，6800岁。隐匿身份的顶尖半妖大能。她在一具具畸形、残缺的半妖骸骨上，悟出了世间唯一真实且残忍的终极建筑力学与阵法美学。(T7)" },
                            { n: "执棋者苏幕遮", t: "春秋暗手", d: "春秋楼神秘莫测的执棋者，7500岁。掌握因果推演法则，将大荒中所有拥有禁忌血脉的半妖视为搅乱腐朽阶级格局的最佳黑子，冷酷地暗中操盘着无数生灵的兴衰。(T7)" },

                            /* --- T8 大乘·半妖至尊（7位，大限12960岁，特例如龟族更长）--- */
                            { n: "阿满", t: "大乘绝巅", d: "凡人血脉逆天成圣的武道巅峰，11000岁。大乘初期，纯粹的肉身之力免疫一切神魂与高阶法术攻击。半妖的终极守护图腾，只要她立于大荒，正道便不敢对半妖赶尽杀绝。(T8)" },
                            { n: "深渊观察者", t: "最古半妖", d: "活了极为久远的最古老半妖，12500岁。大乘中期，血脉源头已因岁月更迭而无法辨认。从不轻易插手因果，只作为沉默的记录者，将大荒半妖的存亡与屈辱刻录于石碑。(T8)" },
                            { n: "织天", t: "半蚕天工", d: "半蚕半人的织造之祖，10800岁。大乘后期，一根法则之丝便能织出一方容纳活物的小天地。她织的天衣无形无质可硬抗天劫，半妖圣女出嫁皆以穿其所织嫁衣为毕生荣耀。(T8)" },
                            { n: "移山", t: "半熊力士", d: "半熊半人的大乘老祖，9500岁。身形壮硕犹如远古神山，脾气火爆但对同族心地纯善。曾以一己之力生生截断地脉，将一座巨型山脉搬移，只为给脆弱的半妖村庄抵挡凛冬北风。(T8)" },
                            { n: "渡厄", t: "半龟寿者", d: "半龟半人的长寿老祖，45000岁（受龟族血脉加持超越人族大限）。大乘巅峰。她漫长的生命见证了半妖一族从太古至今的屈辱史，在寿元枯竭前正将记忆化为大道传承。(T8)" },
                            { n: "破晓", t: "半鸾歌者", d: "半鸾半人的音修大能，11500岁。大乘中期。其法则鸣叫声可强行驱散万魔之祖的污染迷障。常年游荡于九幽边缘，用歌声指引那些迷途或走火入魔的半妖找到最终的庇护所。(T8)" },
                            { n: "枯骨圣手", t: "病态老祖", d: "万灵衍化宗的宗主药师，12000岁。大乘巅峰。极度疯狂的生命学者，将半妖血脉的融合视为宇宙进化的终极答案，对世间一切特殊的混血体质展现出令人毛骨悚然的狂热追捕欲。(T8)" },

                            /* --- T9 渡劫·半妖神话（5位，大限10万岁）--- */
                            { n: "始祖", t: "第一半妖", d: "传说中天地间诞生的第一个半妖，85000岁。渡劫中期。其血脉是一切半妖畸变与潜能的起源。虽在仙魔正史的典籍中被彻底抹去名讳，却隐于岁月长河默默守护着每一个混血后裔。(T9)" },
                            { n: "白涅", t: "涅槃半凤", d: "半凤半人的活传奇，78000岁。渡劫初期。历经七次天道死劫涅槃皆未陨落，每次涅槃都褪去一层杂质。虽其法则力量已无限接近纯血太古凤凰，却毅然决然选择留在底层半妖之中。(T9)" },
                            { n: "归墟", t: "归墟之主", d: "半鲸半人的深海至尊，92000岁。渡劫后期。真身只在四海极地的归墟海沟最深处沉睡。每一次呼吸翻身都会掀起淹没一洲的滔天巨浪，被远古海族奉为不可名状的恐怖神明。(T9)" },
                            { n: "灭世雷罚", t: "天道杀机", d: "大荒天道为抹杀禁忌血脉强行凝聚的雷劫化身，存在岁月不可考。渡劫巅峰法则。却在无尽劈落的紫霄神雷与因果抹杀中，对那些顽强如杂草般的逆天半妖意志产生了一丝违背设定的怜悯。(T9)" },
                            { n: "织梦鼎灵", t: "太初器灵", d: "云梦泽镇泽半仙器太初织梦鼎苏醒的器灵，98000岁。渡劫巅峰。在无尽的星光与因果推演中，它试图寻找一条能让整个半妖一族逃脱天道无情抹杀的终极命运锚点。(T9)" },

                            /* --- EX 禁忌·未可知（2位，超越岁月）--- */
                            { n: "完人", t: "完美融合", d: "传说中人与妖血脉达到完美融合的唯一存在，年龄与纪元同在。毫无排斥与冲突，兼具两族凌驾于大道的全部天赋。只存在于最古老的半妖歌谣中：她在黎明与黄昏的虚妄边界行走。(EX)" },
                            { n: "裂天", t: "逆天半妖", d: "一个连最高阶的紫霄混沌神雷都无法劈死的半妖老妪，不知活了多少个量劫纪元。全修真界的史书与天机阁的命盘都不曾记载她的存在，却总在关乎大荒存亡的绝世异数降生时，于雷云深处投下注视。(EX)" }
                        ]
                    },
                    "鬼族": {
                        L: "九幽魂格",
                        R: [
                            "残缺游魂 (三魂七魄残缺不全 一阵阴风就能吹散 灵智混沌)",
                            "地缚灵 (怨念系于一地 无法离开半步 生生世世困在原地)",
                            "百年孤魂 (游荡人间百年无人祭奠 魂力稀薄记忆消散大半)",
                            "无主水鬼 (溺亡水中冤魂不散 潜伏水底寻找替身)",
                            "上吊缢鬼 (脖颈一道紫黑勒痕 吐着长舌 寻找下一个上吊者)",
                            "饿死鬼 (肚大如鼓喉细如针 永远处于饥饿 见什么吃什么)",
                            "替死鬼格 (必须引诱活人替死 方能挣脱束缚进入轮回)",
                            "画中魂 (魂魄困于画卷之中 画中世界便是全部天地)",
                            "镜中魅 (栖息于铜镜之内 镜面倒影便是她的囚笼)",
                            "无头鬼 (身首异处魂魄不全 双手捧着自己头颅行走)",
                            "敲门鬼 (夜半三更挨家叩门 门开则死 门不开便缠三世)",
                            "夜啼鬼 (彻夜哭嚎不止 哭声入耳令人癫狂崩溃)",
                            "坟头幽光 (坟头飘荡的磷火 只余一缕残念 连鬼都算不上)",
                            "千年红衣厉鬼 (大红嫁衣怨气冲天 千年道行 见者必死)",
                            "青面獠牙鬼将 (鬼中猛将 青面獠牙手持鬼头大刀 可统领百鬼)",
                            "修罗战魂 (古战场战死英魂 煞气不灭 结成修罗战阵)",
                            "子母煞鬼 (一尸两命母子双魂 怨念交织 凶煞无比)",
                            "五通神 (民间淫祠邪神 受香火供奉 实为摄精夺魄之鬼)",
                            "山魈鬼魅 (独足反踵 喜食人脑 山林之中勾引迷路之人)",
                            "罗刹恶鬼 (嗜血成性面目狰狞 以人血肉为食 力大无穷)",
                            "摄魂鬼使 (一摇铃铛便勾人魂魄 专收将死之人的魂灵)",
                            "勾魂黑白使 (冒充地府鬼差 黑白二色 专吸活人阳气)",
                            "极阴鬼煞 (极阴之地孕育而成 至阴至煞 靠近便骨髓生寒)",
                            "九幽黄泉摆渡人 (一叶扁舟渡人往生 收你生前最珍贵之物做船资)",
                            "紫僵/白僵 (初诞僵尸 浑身僵硬关节难弯 只凭本能吸食鲜血)",
                            "绿毛飞僵 (遍体绿毛纵跳如飞 铜皮铁骨 不惧寻常法器)",
                            "千年跳尸 (一跳百丈 力大无穷 可徒手撕裂金丹修士)",
                            "不化骨雏形 (骨骼初具灵性 死后千年不腐 僵尸修道之始)",
                            "铜甲尸 (浑身如铜铸 刀枪不入水火不侵 灵智已开可修尸道)",
                            "金甲尸王 (金甲覆体万法不侵 尸中称王 可号令万千行尸)",
                            "旱魃血脉 (所过之处赤地千里大旱三年 火中恶魔 天灾化身)",
                            "将臣血脉 (吸血僵尸始祖血脉 可化蝠飞行 不死不灭)",
                            "赢勾血脉 (身携幽冥之水 水淹三界 尸中水神)",
                            "后卿血脉 (诅咒之源 一言一语皆是诅咒 言出法随)",
                            "幽冥皇族之血 (鬼中贵胄 生来便掌阴司权柄 百鬼莫敢不敬)",
                            "十殿阎罗候选人 (冥府储君 身具阎罗印记 有望角逐十殿之位)",
                            "判官转世魂格 (前世为冥府判官转世 手中判笔能判人罪孽)",
                            "地藏谛听魂格 (魂中带谛听之能 伏地一听便知三界因果)",
                            "轮回盘碎裂之魂 (不入轮回不归地府 天地不收的孤魂野鬼)",
                            "忘川河伯 (执掌忘川一河 河水皆是罪孽所化 渡河便是渡罪)",
                            "酆都鬼帝嫡系 (酆都鬼帝血脉后裔 鬼中皇族 阴司太子)",
                            "阿鼻地狱受刑者 (永世困于阿鼻地狱 万劫不灭 怨念深重)",
                            "阴神神格雏形 (神位初显 不再是鬼 而是鬼神之始)",
                            "九天玄刹鬼子 (天生鬼煞 降生便引动九天玄雷 大凶大吉)",
                            "天璇陨星怨魂 (被天璇圣地重力阵法生生压碎的万千冤魂聚合体)",
