                        C: [
                            /* --- T1 炼血·魔途初窥（5位，高危死亡区，寿元极短）--- */
                            { n: "哑女", t: "凡人魔胎", d: "魔教祭坛的逃生者，16岁。被强行种下魔种，眼神中藏着疯狂的杀意。因魔气反噬失去言语能力，唯独喜欢用带着血垢的指甲在墙壁上刻画深渊符文。(T1)" },
                            { n: "血娃", t: "血池魔童", d: "无间魔宗万人血祭坑里唯一存活的变异婴儿，8岁。皮肤泛着不正常的青紫色。极度渴望鲜血，吸食高阶修士遗骸的精血时眼中会闪烁诡异的红光，是魔宗底层极度危险的异类。(T1)" },
                            { n: "阿弃", t: "炮灰弃子", d: "万灵衍化宗丢弃在死尸堆里的魔化残次品，35岁。右臂畸形比大腿还粗，脑子混沌不清。全靠本能吞噬腐肉与废弃残肢为生，是魔域最低贱的清道夫。(T1)" },
                            { n: "小药魔", t: "残毒药奴", d: "万法阁暗中用来试魔毒的凡人幼童，12岁。满脸毒疮，早已在无尽的折磨中丧失了痛觉。依靠偷偷舔舐试药残渣中微弱的魔气，在剧毒中畸形苟活。(T1)" },
                            { n: "锁链鬼", t: "底阶狱卒", d: "大虞天牢最底层的半人半魔怪物，45岁。手持生锈铁链每天鞭打囚犯吸食痛苦与怨气，却又常在被高阶魔修毒打后，像野兽般躲入阴暗角落独自舔舐伤口。(T1)" },

                            /* --- T2 筑魔·嗜血淬骨（4位，大限120岁，常靠邪术强撑）--- */
                            { n: "小魔头", t: "练气少主", d: "无法无天的魔宗二世祖，30岁。浑身挂满高阶护身符和一次性魔宝，嚣张跋扈。实则极度畏死，遭遇不可敌的强者时会毫不犹豫地血祭身边的随从换取遁术发动。(T2)" },
                            { n: "红骨女", t: "初阶骨魔", d: "修炼白骨道的初期魔修，80岁。生生剥去自己半张脸皮露出血红颧骨为美。性格乖戾扭曲，喜好将猎杀的年轻修士骨骼雕刻成阴森的骨簪等残忍法器。(T2)" },
                            { n: "灰袍老怪", t: "收尸人", d: "古战场边缘专门捡漏的魔修老翁，150岁（常年吸食尸气强行延寿）。背着巨大的储物破布袋，像食腐秃鹫般徘徊于死人堆中，扒取残破法宝与浸血的魔功残卷。(T2)" },
                            { n: "贪灵蛛", t: "底层蛛魔", d: "上半身是丑陋妇人下半身是毒蜘蛛的魔物，110岁。盘踞于黑暗森林外围以结网捕杀凡人与低阶散修为生。极度贪婪狡诈，只要给出足够血食便会毫不犹豫出卖同族的领地坐标。(T2)" },

                            /* --- T3 真魔·初露魔角（5位，大限200岁）--- */
                            { n: "血公子", t: "真魔散魔", d: "嗜血如命的变态魔修，180岁。喜好收集大荒各族绝色天骄的鲜血，用以酿造破境的血灵酒。手段残忍却极其讲究所谓“猎杀美学”，对衣着邋遢的猎物甚至懒得出剑斩杀。(T3)" },
                            { n: "合欢圣女(外门)", t: "真魔魅魔", d: "精通极道采补之术的外门妖女，160岁。常以清纯面目诱杀正道翘楚，在利用双修鼎炉之法榨干对方的修为底蕴后，将枯骨随手抛弃，是令人闻风丧胆的带刺玫瑰。(T3)" },
                            { n: "断指琴师", t: "天音堕落者", d: "原天音宗弟子，220岁（以怨气续命）。因嫉妒斩断同门十指被逐，彻底堕入魔道。如今以森森白骨为指弹奏魔琴，琴音专勾引闻者心底最深处的怨憎与杀念，令其自相残杀。(T3)" },
                            { n: "铜尸恶汉", t: "赶尸魔修", d: "带着三具高大铜尸游走的胖大头陀，190岁。表面笑脸迎人，实则暗中寻觅极品体修苗子，随时准备将猎物的四肢打断、灌入水银，活生生炼制成第四具铜尸。(T3)" },
                            { n: "绣皮娘", t: "霓裳弃徒", d: "从霓裳宗叛逃的疯魔织女，250岁。嫌弃天蚕丝不够坚韧，转而以高阶修士的皮囊与抽出的经脉织布。其编织的“怨气血衣”防御极高，但靠近时常能听见亡魂的凄厉惨叫。(T3)" },

                            /* --- T4 魔相·法相初聚（5位，大限500岁）--- */
                            { n: "厉九幽", t: "魔胎魔子", d: "无间魔宗第一魔子，280岁。觉醒了罕见的深渊吞噬体。专靠疯狂吞噬同门金丹与魔核晋升，视大荒万族天骄为待宰的口粮，是正道黄金一代的终极噩梦。(T4)" },
                            { n: "姜焱", t: "姜家疯少", d: "荒古姜家走火入魔的天才少爷，120岁。为掌控极道异火将灵魂献祭给域外魔神。如今全身燃烧着无法熄灭的黑炎，敌我不分，如同一颗随时会引爆一城的移动火种。(T4)" },
                            { n: "影烟", t: "影魔刺客", d: "影魔一族的最强女刺客，350岁。灰白短发遮掩下是一双没有瞳孔的纯黑眼眸。隐匿如烟，在深渊黑市接单从不失手，其定下的唯一铁律是不接刺杀孤儿的悬赏。(T4)" },
                            { n: "红绡", t: "欲魔掌柜", d: "合欢宗叛逃的欲魔，480岁。一身红纱风情万种，嘴角点着美人痣。厌倦了无尽的采补杀戮后，在法外之地开起茶馆，常以掺杂剧毒魔气的苦茶试探过客的道心。(T4)" },
                            { n: "骨笙", t: "骨魔乐师", d: "骨魔一族的女乐师，500岁。浑身骨骼剔透如玉，常折断自身肋骨作为乐器弹出凄厉曲调。游走于尸山血海的战场，借吸收战死者的绝望怨气来淬炼其不化骨躯。(T4)" },

                            /* --- T5 魔尊·魔焰滔天（5位，大限1000岁，多有血祭续命手段）--- */
                            { n: "枯骨老人", t: "魔相邪修", d: "修白骨道的残忍巨擘，1100岁（频繁血祭活人延寿）。浑身干瘪如柴，最爱将鲜活神魂封入骨雕中日夜折磨。在大荒白骨山建有万骨行宫，位列大虞皇朝通缉榜前十。(T5)" },
                            { n: "绝情魔女", t: "瑶池弃仙", d: "瑶池圣地前代圣女，850岁。因动情被废修为后堕魔，亲手将曾经的至爱千刀万剐。一袭黑衣手持魔兵，立誓斩尽天下有情人，剑意中透着冰冷彻骨的极致疯狂。(T5)" },
                            { n: "公输狂", t: "堪舆疯匠", d: "被堪舆九玄局逐出的大匠师，980岁。将机关术与深渊魔骨结合，把自己改造成半机械半魔物的憎恶体。其地下工坊挂满了被活体解剖的修士傀儡与血肉材料。(T5)" },
                            { n: "焰姬", t: "炎魔后裔", d: "炎魔一族仅存的遗孤，1200岁。满头火红长发无风自舞，皮肤下流淌着毁灭岩浆。性情暴虐极易失控，每一次怒火爆发都会令方圆百里的生灵化作焦土残骸。(T5)" },
