                        C: [
                            /* --- T1 引气·微尘初醒（6位，底层微末之灵）--- */
                            { n: "小草", t: "草木精怪", d: "一株刚开智的狗尾巴草，本体寿命约30年。灵智初开只会本能地发出对水属灵气的渴望。胆子极小，遭遇任何风吹草动或微弱杀气，就会瞬间散去灵力波动，僵死伪装成最普通的凡间杂草。(T1)" },
                            { n: "砚童", t: "墨池精怪", d: "大儒书房废墨池里爬出来的墨团精怪，存在约150年。只会咿咿呀呀地发出含糊音节，其研出的墨汁天然带有微弱的灵气导向，是修真界底层符师极其渴求的制符辅料。(T1)" },
                            { n: "灯芯儿", t: "青灯精怪", d: "古庙青灯掉落的灯花开智，存在约200年。没有实体，仅是一点悬浮的黄豆大火光。对阴煞之气极其敏感，一旦感知到幽冥鬼气靠近便会剧烈闪烁，常被低阶修士捉去充当预警法器。(T1)" },
                            { n: "石滚滚", t: "顽石通灵", d: "深山阶梯上最普通不过的青石板成精，存在约300年。没有四肢只能靠滚动前行，但本体经历了岁月风化极其坚硬。曾在一次大宗门斗法中被高阶剑气削去一角，从此只剩半个脑袋。(T1)" },
                            { n: "露珠儿", t: "晨露之灵", d: "千年古树叶上吸收了日月精华的露水凝聚成形的小妖精，每日清晨重塑，日出即散。她滴落的纯净泪水是极佳的凡阶疗伤药，但其本体极度脆弱，无法承受任何灵力捕获。(T1)" },
                            { n: "书虫", t: "书页蠹虫", d: "常年啃食修真经书残卷而开启灵智的灵虫，存在约120年。虽然毫无战斗力，但其微小的神识中储存了大量残缺的低阶功法与杂书记忆，如同一个微型的活体藏经阁。(T1)" },

                            /* --- T2 炼体·聚灵化形（5位，初步凝聚法则）--- */
                            { n: "参爷", t: "万年宝药", d: "一株长出四肢五官的万年人参娃娃，存在逾12000年。极度怕死，土遁速度极快。其本体蕴含的磅礴生机让它成为全修真界通缉的移动宝库，终日都在提防被大宗门长老抓去炼成人体大丹。(T2)" },
                            { n: "剑匣奴", t: "剑匣木偶", d: "某位陨落剑修遗留的沉重机关木偶，存在约800年。背后背着一个巨大的空剑匣，没有痛觉。只会死板且机械地执行“替主扛剑”的底层指令，坚硬的铁木之躯布满剑痕。(T2)" },
                            { n: "泥娃娃", t: "息壤残渣", d: "传说中九天息壤掉落的一点边角料泥巴开智，存在约5000年（开智极缓）。长得像个泥塑的胖娃娃，天生亲和土系法则，极其擅长改变地脉走向，能在一息之间熔穿百丈深的坚硬岩层。(T2)" },
                            { n: "铃铛仙", t: "古寺铜铃", d: "悬挂于古寺檐角数百年的铜铃化灵，存在约600年。声音清脆，附带微弱的佛门破妄法则，能驱散低阶妖魅的幻术。常年伴随风雨飘荡，性格极其敏感警惕。(T2)" },
                            { n: "火折子", t: "凡火开灵", d: "沾染了高阶修士本命灵气而开智的凡火火折子，存在约200年。虽无法像天地异火般焚天煮海，但在灵气被彻底封禁的极寒绝境中，其点燃的火星能无视法则冻结，提供一丝极其珍贵的温度。(T2)" },

                            /* --- T3 筑基·奇物初显（5位，可化虚为实）--- */
                            { n: "剑痴小剑", t: "残剑剑灵", d: "上古战场遗留的一把断剑之灵，存在逾2500年。除了剑道推演之外毫无常识，终日在废墟中寻人比划。虽只剩半截锈迹斑斑的剑身，但只要被注入灵力，便能爆发出远超筑基期的凌厉剑芒。(T3)" },
                            { n: "阵灵小童", t: "残阵之灵", d: "远古破败迷阵中汲取天地灵气诞生的阵灵，存在约3000年。手里总是攥着几面破旧的阵旗。虽无正面搏杀之力，但对天地阵纹的流动有着近乎直觉的敏锐，能生生拆解绝大多数低阶杀阵。(T3)" },
                            { n: "丹香女", t: "废丹成精", d: "大宗门炼丹房废料堆里意外揉合数千种灵药残渣成形的灵族，存在约400年。周身散发着极度复杂的奇特香气。其血液中和了无数药性，不仅能解百毒，甚至能滋养枯萎的灵草。(T3)" },
                            { n: "画卷童子", t: "山水画灵", d: "一幅破损古山水画里走出的水墨童子，存在约1200年。掌握低阶空间法则，能将活物拉入画中水墨世界短暂隐匿。但画卷本体极其脆弱，承受不住金丹期以上的威压波及。(T3)" },
                            { n: "酒葫芦", t: "灵酒器灵", d: "浸泡在百年灵酒中化形的器灵，存在约1100年。显化为终日醉醺醺的红鼻头老翁。其葫芦内自成空间，倒出的灵酒不仅能瞬间填补枯竭的灵力，还附带短暂屏蔽肉身痛觉的麻痹法则。(T3)" },

                            /* --- T4 金丹·异象显化（6位，质变之始）--- */
                            { n: "花仙子", t: "金丹木灵", d: "大宗门百花园中灵力最盛的草木精怪化形，存在约2500年。精通木系疗愈法术，周身萦绕百花精气。只要双足踏于未被污染的大地之上，便能源源不断地汲取纯净的地脉生机。(T4)" },
                            { n: "石敢当", t: "金丹石灵", d: "一座灵脉核心的泰山石成精，存在约4500年。憨厚老实，将所有天赋全部点在防御法则上。斗法时能直接显化为一座小型岩石山岳，其坚硬程度足以硬抗同阶高手的本命法宝轰击。(T4)" },
                            { n: "琴魂·商音", t: "天音弃琴", d: "天音宗抛弃的一把断尾古琴孕育之灵，存在约2800年。性格清冷孤傲，极少显化白衣女子的虚影。其琴弦虽断，但拨动时发出的商音法则能破除心魔幻障，并令方圆百丈内的灵气陷入凝滞。(T4)" },
                            { n: "堪舆齿轮", t: "机关核心", d: "堪舆九玄局废弃的高阶机关核心部件化灵，存在约3200年。显化为一颗漂浮的精密铜齿轮球。拥有堪称恐怖的拓印记忆力，大荒中任何只被扫描过一眼的复杂秘境地形，皆能完美复刻在核心内。(T4)" },
                            { n: "云姬", t: "云朵化形", d: "天边一抹吸纳了至阳灵气的晚霞化形，存在约2000年。金丹巅峰修为。身着霓裳，发丝如流云，容貌随天光变化。生性散漫爱自由，居无定所，常在云海深处随风飘荡。(T4)" },
                            { n: "火灵儿", t: "丹炉炉灵", d: "地阶极品炼丹炉成精的少女，存在约3500年。金丹期法则掌控。一头红发高高束起，脾气与炉中真火一般狂暴，稍有不顺便会直接炸炉，但一旦成功控火，炼出的丹药皆带极品丹纹。(T4)" },

                            /* --- T5 元婴·灵聚真身（5位，大荒奇珍）--- */
                            { n: "墨香", t: "元婴画仙", d: "传世古画成精的温婉灵修，存在约6500年。精通化虚为实的极致幻术。其笔墨能直接欺骗元婴期大能的神识感知，曾泼墨绘出一支以假乱真的千人重甲军阵，在战场上生生逆转战局。(T5)" },
                            { n: "冰髓老怪", t: "极北冰灵", d: "极北冰原深处万载玄冰髓成精的古老灵体，存在逾15000年。性格极其古怪孤僻。掌控玄冰本源法则，若不惜燃烧本源代价，可释放出一记连空间流速都能冻结一瞬的“绝对零度”。(T5)" },
                            { n: "星陨剑灵", t: "天璇重剑", d: "天璇圣地重力剑冢中孕育而出的狂暴剑灵，存在约8000年。化形为一个手持无锋巨剑的魁梧男子。其每一击都自带星陨坠落的恐怖重压法则，在近身肉搏领域几乎达到了同阶的碾压态。(T5)" },
                            { n: "镜心", t: "铜镜镜仙", d: "一面摄取了无数灵气的千年古铜镜之灵，存在约4200年。元婴中期。曾是世俗深宫的梳妆镜，洞悉无数人心鬼蜮。精通面容与命格的伪装术，能用镜光剥离或重塑他人的外在因果。(T5)" },
                            { n: "玉磬", t: "古钟钟灵", d: "隐世古寺钟声凝结化形的音之法则灵族，存在约5500年。元婴巅峰。一身素衣手持小钟，周身常有梵音缭绕。其破晓时分的钟声能涤荡方圆千里的邪魔外道，曾将企图炼化她的魔修震得道心崩碎。(T5)" },

                            /* --- T6 化神·掌控法则（5位，天地异宝）--- */
                            { n: "炎魔", t: "化神异火", d: "大荒排名前列的天地异火化形，存在逾25000年。脾气火爆到了极点，处于随时可能玉石俱焚的狂暴边缘。其火焰蕴含极致的毁灭法则，一旦全面爆发，足以将方圆千里的城池与地脉化为焦土。(T6)" },
                            { n: "书灵老朽", t: "化神器灵", d: "万法阁最深处藏书阁的宗门底蕴级器灵，存在约38000年。知晓大荒万事，但逻辑极为繁琐。其庞大的灵体内刻录着整个修真界三分之一的失传秘典，能瞬间推演并破解世间绝大多数五行法术的门道。(T6)" },
                            { n: "天机镜仙", t: "占星残镜", d: "天机阁占星台曾被天谴劈碎的远古铜镜之灵，存在逾45000年。双眼蒙着白布，却能洞穿世间一切因果幻象。因受过天道反噬，从不道破完整的未来，只留下极其隐晦的命运谶语。(T6)" },
