                    "一枚掉落在凡间、沾染了红尘气的功德金钱": "金钱温润不俗，既有功德清光，也有人间烟火，能买路也能挡灾。",
                    "一把没有伞面只有玄铁伞骨的防身机括伞": "伞骨开合如机关兽咬合，可挡暗器也能近身反击，只是看起来寒酸。",
                    "一块在魔血中浸泡千年却依然纯白的无垢石": "白石不染魔污，握着它能稳住灵台，是黑暗里少见的干净之物。",
                    "一册会自动记录周围人死亡倒计时的无字竹简": "竹简平时无字，靠近将死之人便浮现倒计时，知道答案本身就是诅咒。"
                });

                const itemDescription = (name) => ITEM_DESCRIPTIONS[name] || "";

                const enrichItemDescription = (name, desc) => desc || itemDescription(name) || "";

                const luckDescription = (name) => {
                    const found = DB.Global.Luck.find(item => item.n === name);
                    return found ? found.d : "";
                };

                const fieldInfo = (id) => {
                    const custom = I(id + '_c');
                    if (custom && !custom.classList.contains('hidden') && custom.value) {
                        const parsed = splitNameDesc(custom.value);
                        const customDesc = id === 'i_it'
                            ? enrichItemDescription(parsed.name, parsed.desc) || "自定义外物，按字面设定推演来历、用途与限制。"
                            : parsed.desc;
                        return { name: parsed.name, desc: customDesc };
                    }
                    const el = I(id);
                    if (!el) return { name: "未知", desc: "" };
                    const parsed = splitNameDesc(el.value || el.dataset.n || "");
                    const name = parsed.name || el.dataset.n || "未知";
                    const datasetMatches = (el.dataset.raw && el.dataset.raw === el.value) || el.dataset.n === name;
                    let desc = parsed.desc || (datasetMatches ? (el.dataset.d || "") : "");
                    if (id === 'i_it') desc = enrichItemDescription(name, desc);
                    else if (id === 'i_lk') desc = desc || luckDescription(name);
                    return { name, desc: desc || "" };
                };

                const fieldName = (id) => fieldInfo(id).name;

                const fieldRefLine = (label, id) => {
                    const data = fieldInfo(id);
                    return `- ${label}：${data.name}${data.desc ? `；描述=${data.desc}` : ''}`;
                };

                const itemRefText = () => {
                    const data = fieldInfo('i_it');
                    return data.desc ? `${data.name}；描述=${data.desc}` : data.name;
                };

                const buildNarrativeReference = (rule) => {
                    const gfRefTxt = gongfaSlots.length > 0
                        ? gongfaSlots.map(gf => `- 功法《${gf.name}》：品阶=${gf.rank}；修炼层数=${gf.layer}；叙事效果=${gf.effect}`).join('\n')
                        : '- 功法：无';
                    const stRefTxt = shentongSlots.length > 0
                        ? shentongSlots.map(st => `- 神通《${st.name}》：品阶=${st.rank}；熟练度=${st.prof}；叙事效果=${st.effect}`).join('\n')
                        : '- 神通：无';
                    const bondLines = [];
                    if (selectedComps.size > 0) {
                        selectedComps.forEach((val) => {
                            const cComp = val.comp;
                            const cRel = val.rel;
                            bondLines.push(`- 羁绊：NPC=${cComp.n}；关系=${cRel ? cRel.n : '未知'}；关系描述=${cRel ? cRel.d : '无'}；人物参考=${cComp.d || '无'}`);
                        });
                    } else {
                        bondLines.push('- 羁绊：无');
                    }
                    return [
                        `- 命轨难度：${rule.title}（${rule.promptHint}）`,
                        '- 战力准则：T1-T9分别为感气/炼体/筑基/金丹/元婴/化神/合体/大乘/渡劫或异族同阶；每境细分初期/中期/后期/巅峰，数值按初期×1.0/1.2/1.5/1.8。跨境天堑必须绝对执行，T1-T4跨1大境艰难、跨2大境自动失败；T5+只有巅峰对高一境初期存在死战窗口，其余跨境不可凭天赋/体质/神通/法宝硬破。',
                        '- 数值基准：战力T1=100,T2=1000,T3=8000,T4=80000,T5=500000,T6=5000000,T7=50000000,T8=300000000,T9=1000000000；命T1=10,T2=100,T3=800,T4=5000,T5=30000,T6=180000,T7=1000000,T8=6000000,T9=30000000。',
                        '- 灵与神识基准：灵T1=8,T2=80,T3=640,T4=4000,T5=24000,T6=144000,T7=800000,T8=4800000,T9=24000000；神识T1=5,T2=50,T3=400,T4=2500,T5=15000,T6=90000,T7=500000,T8=3000000,T9=15000000。',
                        '- 功法神通品阶准则：常规下界品阶只按当前境界上限随机，黄=T1-T3，玄=T4-T6，地=T7-T8，天=T9；仙/王/帝/道属于上界阶梯，不应在下界常规随机出现。本面板随机到“仙”时是10%特殊仙法彩蛋，应按具体效果叙事，不得当作真正T10仙经赋予越境碾压。',
                        fieldRefLine('灵根', 'i_rt'),
                        fieldRefLine('体质', 'i_bd'),
                        fieldRefLine('气运', 'i_lk'),
                        fieldRefLine('随身外物', 'i_it'),
                        `- 前尘旧梦：${I('i_ds').value}`,
                        gfRefTxt,
                        stRefTxt,
                        bondLines.join('\n')
                    ].join('\n');
                };

                const P = (i, o) => {
                    if (!o || o.length === 0) return;
                    const val = o[Math.floor(Math.random() * o.length)];
                    let name, rawVal, desc = "", t = "", v = "";
                    if (typeof val === 'string') {
                        rawVal = val;
                        let m = val.match(/^(.*?)(?:\s*\((.*?)\))?$/);
                        name = m[1] ? m[1].trim() : val;
                        if (m[2]) desc = m[2].trim();
                        if (i === 'i_it') desc = enrichItemDescription(name, desc);
                    } else {
                        rawVal = val.n; name = val.n; desc = val.d || ""; t = val.t || ""; v = val.v || "";
                    }
                    if (I(i)) {
                        I(i).value = rawVal;
                        I(i).dataset.n = name;
                        I(i).dataset.d = desc;
                        I(i).dataset.t = t;
                        I(i).dataset.v = v;
                    }
                    if (I('disp_' + i)) {
                        I('disp_' + i).innerText = name;
                        I('disp_' + i).style.color = "var(--accent-gold)";
                    }
                };

                /* ══════════════════════════════════
                   [弹窗系统] DOM缓存 + 搜索筛选 + 事件委托
                ══════════════════════════════════ */
                const _modalCache = new Map();
                let _modalCurrentId = '';
                let _modalFilterTimer = null;

                const buildModalKey = (id, rc) => {
                    if (id === 'i_rt' || id === 'i_bd' || id === 'i_it' || id === 'i_lc' || id === 'i_cl') return id + '_' + rc;
                    return id;
                };

                const parseModalArr = (arr, id) => arr.map(item => {
                    let name, desc = "", rawVal, t = "", v = "";
                    if (typeof item === 'string') {
                        rawVal = item;
                        let m = item.match(/^(.*?)(?:\s*\((.*?)\))?$/);
                        name = m ? (m[1] ? m[1].trim() : item) : item;
                        if (m && m[2]) desc = m[2].trim();
                        if (id === 'i_it') desc = enrichItemDescription(name, desc);
                    } else {
                        rawVal = item.n; name = item.n; desc = item.d || ""; t = item.t || ""; v = item.v || "";
                    }
                    return { rawVal, name, desc, t, v };
                });

                const renderModalItems = (dataArr, id, isShort) => {
                    const frag = document.createDocumentFragment();
                    dataArr.forEach((data, idx) => {
                        let displayDesc = data.desc ? data.desc : (isShort ? "天道基础法则。" : "大道隐蔽，天机未注详名。");
                        const item = document.createElement('div');
                        item.className = 'comp-item';
                        item.dataset.modalIdx = idx;
                        item.dataset.modalId = id;
                        item.dataset.searchText = (data.name + ' ' + data.desc + ' ' + data.t).toLowerCase();

                        const info = document.createElement('div');
                        info.className = 'comp-info';

                        const nameDiv = document.createElement('div');
                        nameDiv.className = 'comp-name modal-item-name';
                        nameDiv.textContent = data.name;
                        if (data.t) {
                            const tSpan = document.createElement('span');
                            tSpan.className = 'modal-item-tier';
                            tSpan.textContent = '[' + data.t + ']';
                            nameDiv.appendChild(tSpan);
                        }

                        const descDiv = document.createElement('div');
                        descDiv.className = 'comp-desc';
                        descDiv.textContent = displayDesc;

                        info.appendChild(nameDiv);
                        info.appendChild(descDiv);
                        item.appendChild(info);
                        frag.appendChild(item);
                    });
                    return frag;
                };

                window.OpenSysModal = (id, title) => {
                    const rc = I('i_rc') ? I('i_rc').value : "人族";
                    let arr = [];

                    if (id === 'i_rt') arr = DB[rc].R;
                    else if (id === 'i_bd') arr = DB[rc].B;
                    else if (id === 'i_it') arr = DB[rc].I;
                    else if (id === 'i_lc') arr = DB[rc].P;
                    else if (id === 'i_lk') arr = DB.Global.Luck;
                    else if (id === 'i_rc' || id === 'i_comp_rc') arr = ["人族", "妖族", "半妖", "鬼族", "魔族", "灵族"];
                    else if (id === 'i_gd') arr = ["男修", "女修", "混沌"];
                    else if (id === 'i_cl') arr = RACE_LEVELS[rc] || RACE_LEVELS["人族"];

                    const cacheKey = buildModalKey(id, rc);
                    const isShort = (id === 'i_rc' || id === 'i_gd' || id === 'i_cl' || id === 'i_comp_rc');

                    if (!_modalCache.has(cacheKey)) {
                        const dataArr = parseModalArr(arr, id);
                        const frag = renderModalItems(dataArr, id, isShort);
                        _modalCache.set(cacheKey, { data: dataArr, dom: frag.cloneNode(true), frag });
                    }

                    const cached = _modalCache.get(cacheKey);
                    window.currentModalData = cached.data;
                    _modalCurrentId = id;

                    const list = I('sys_modal_list');
                    list.innerHTML = '';
                    list.appendChild(cached.dom.cloneNode(true));

                    I('sys_modal_title').textContent = title;
                    const filterInput = I('sys_modal_filter');
                    filterInput.value = '';
                    filterInput.style.display = isShort ? 'none' : '';
                    I('sys_modal').classList.remove('hidden');
                    if (!isShort) filterInput.focus();
                };

                /* 搜索筛选 */
                I('sys_modal_filter').addEventListener('input', function() {
                    clearTimeout(_modalFilterTimer);
                    const kw = this.value.trim().toLowerCase();
                    _modalFilterTimer = setTimeout(() => {
                        const items = I('sys_modal_list').querySelectorAll('.comp-item');
                        items.forEach(item => {
                            if (!kw) { item.style.display = ''; return; }
                            item.style.display = item.dataset.searchText.includes(kw) ? '' : 'none';
                        });
                    }, 120);
                });

                /* 弹窗列表事件委托 */
                I('sys_modal_list').addEventListener('click', (e) => {
                    const item = e.target.closest('.comp-item[data-modal-idx]');
                    if (!item) return;
                    const idx = parseInt(item.dataset.modalIdx, 10);
                    const id = item.dataset.modalId || _modalCurrentId;
                    let data = window.currentModalData[idx];
                    if (!data) return;

                    let el = I(id);
                    el.value = data.rawVal;
                    el.dataset.n = data.name; el.dataset.d = data.desc; el.dataset.t = data.t; el.dataset.v = data.v;

                    I('disp_' + id).textContent = data.name;
                    I('sys_modal').classList.add('hidden');

                    if (id === 'i_rc') RC();
                    if (id === 'i_gd') rollBodyMetrics(I('i_rc') ? I('i_rc').value : "人族", data.name);
                    if (id === 'i_cl') {
                        syncPracticeRanksToCultivation();
                        window.RenderSkills();
                    }
                    if (id === 'i_comp_rc') window.RenderComp();
                    U();
                });

                /* 关闭弹窗事件委托 */
                I('sys_modal_close').addEventListener('click', () => I('sys_modal').classList.add('hidden'));
                window.CloseOpt = () => I('sys_modal').classList.add('hidden');

                const U = () => {
                    const n = I('i_nm').value || "无名", a = I('i_ag').value, r = I('i_rc').value;
                    I('v_ag').innerText = a; I('p_av').innerText = n.charAt(0); I('p_nm').innerText = n;
                    I('p_rd').innerText = `${r} · ${a}岁`;
                    I('p_rt').innerText = V('i_rt'); I('p_bd').innerText = V('i_bd');
                    I('p_cl').innerText = V('i_cl'); I('p_lc').innerText = V('i_lc');
                    I('p_ds').innerText = I('i_ds').value || "暂无描述";
                    const w = I('p_aw'); w.className = 'avatar-w';
                    const rv = V('i_rt'), bv = V('i_bd');
                    if (rv.includes('天') || rv.includes('道') || rv.includes('龙')) w.classList.add('gold');
                    else if (bv.includes('魔') || r === '魔族' || r === '鬼族') w.classList.add('red');
                    else if (rv.includes('灵') || r === '灵族' || r === '妖族') w.classList.add('purple');
                    w.querySelector('.aura').classList.add('on');
                };

                /* 品阶中文名映射 */
                const TIER_NAMES = {
                    "T0": "凡尘牵绊", "T1": "引气·初窥", "T2": "炼体·淬炼", "T3": "筑基·崭露",
                    "T4": "金丹·锋芒", "T5": "元婴·一方", "T6": "化神·名动", "T7": "合体·霸主",
                    "T8": "大乘·巨擘", "T9": "渡劫·绝巅", "EX": "传说禁忌", "S": "特别限定"
                };

                window.RenderComp = () => {
                    const compRace = I('i_comp_rc') ? I('i_comp_rc').value : "人族";
                    const c = DB[compRace] || DB["人族"];
                    const cl = I('comp_root');
                    if (!cl) return;

                    _compCurrentRace = compRace;
                    cl.innerHTML = '';

                    if (!c.C || c.C.length === 0) { window.RenderSelectedSummary(); U(); return; }

                    /* 按品阶分组 */
                    const groups = new Map();
                    c.C.forEach((p, idx) => {
                        let m = p.d.match(/\((T\d|EX|S)\)$/);
                        let tier = m ? m[1] : 'T1';
                        if (!groups.has(tier)) groups.set(tier, []);
                        groups.get(tier).push({ p, idx, tier });
                    });

                    /* 渲染各品阶折叠组 */
                    groups.forEach((npcs, tier) => {
                        const grp = document.createElement('div');
                        grp.className = 'tier-group';

                        const hasSelected = npcs.some(n => selectedComps.has(compRace + '_' + n.idx));
                        const tierLabel = TIER_NAMES[tier] || tier;

                        grp.innerHTML = `<div class="tier-header" data-tier="${esc(tier)}">
    <div class="tier-header-left">
        <span class="tier-header-rank">${esc(tier)}</span>
        <span class="tier-header-label">${esc(tierLabel)}<span class="tier-header-count">（${npcs.length}位${hasSelected ? ' · 已选' : ''}）</span></span>
    </div>
    <span class="tier-header-arrow">▶</span>
</div>`;
                        cl.appendChild(grp);
                    });

                    window.RenderSelectedSummary();
                    U();
                };

                /* 展开/折叠品阶组 */
                window.ToggleTier = (headerEl) => {
                    const grp = headerEl.parentElement;
                    let body = grp.querySelector('.tier-body');

                    if (headerEl.classList.contains('open')) {
                        headerEl.classList.remove('open');
                        if (body) body.remove();
                        return;
                    }

                    headerEl.classList.add('open');

                    if (!body) {
                        const compRace = _compCurrentRace;
                        const c = DB[compRace] || DB["人族"];
                        const tier = headerEl.dataset.tier;

                        body = document.createElement('div');
                        body.className = 'tier-body';

                        c.C.forEach((p, i) => {
                            let m = p.d.match(/\((T\d|EX|S)\)$/);
                            let t = m ? m[1] : 'T1';
                            if (t !== tier) return;

                            let cleanDesc = p.d.replace(/\s*\((T\d|EX|S)\)$/, '');
                            const mapKey = compRace + '_' + i;
                            const isSelected = selectedComps.has(mapKey);
                            const selectedRel = isSelected ? selectedComps.get(mapKey).rel : null;

                            const item = document.createElement('div');
                            item.className = 'comp-item' + (isSelected ? ' active' : '');
                            item.dataset.tier = t;
                            item.dataset.idx = i;
                            item.dataset.compRace = compRace;

                            const rankDiv = document.createElement('div');
                            rankDiv.className = 'comp-rank';
                            rankDiv.textContent = t;

                            const infoDiv = document.createElement('div');
                            infoDiv.className = 'comp-info';

                            const nameDiv = document.createElement('div');
                            nameDiv.className = 'comp-name';
                            nameDiv.textContent = p.n;
                            if (isSelected && selectedRel) {
                                const tag = document.createElement('span');
                                tag.className = 'chosen-rel-tag';
                                tag.textContent = '已选: ' + selectedRel.n;
                                nameDiv.appendChild(tag);
                            }

                            const descDiv = document.createElement('div');
                            descDiv.className = 'comp-desc';
                            descDiv.textContent = cleanDesc;

                            infoDiv.appendChild(nameDiv);
                            infoDiv.appendChild(descDiv);
                            item.appendChild(rankDiv);
                            item.appendChild(infoDiv);
                            body.appendChild(item);
                        });
                        grp.appendChild(body);
                    }
                };

                /* 羁绊列表事件委托（替代所有内联 onclick） */
                I('comp_root').addEventListener('click', (e) => {
                    /* 品阶折叠头部 */
                    const header = e.target.closest('.tier-header');
                    if (header) { window.ToggleTier(header); return; }

                    /* NPC 卡片点击（排除关系按钮区域） */
                    if (e.target.closest('.rel-bar')) return;
                    const compItem = e.target.closest('.comp-item[data-idx]');
                    if (compItem) {
                        const idx = parseInt(compItem.dataset.idx, 10);
                        const race = compItem.dataset.compRace || _compCurrentRace;
                        window.SelComp(compItem, idx, race);
                    }
                });




                /* RC_UI：仅刷新标签、修为默认值和NPC列表，不随机任何字段 */
                const RC_UI = (r) => {
                    const c = DB[r] || DB["人族"];
                    I('l_rt').innerText = c.L;

                    const defaultLevel = RACE_LEVELS[r] ? RACE_LEVELS[r][0] : "凡人";
                    if (I('i_cl')) {
                        I('i_cl').value = defaultLevel;
                        if (I('disp_i_cl')) I('disp_i_cl').innerText = defaultLevel;
                    }

                    if (I('i_comp_rc')) {
                        I('i_comp_rc').value = r;
                        if (I('disp_i_comp_rc')) I('disp_i_comp_rc').innerText = r;
                    }
                    window.RenderComp();
                };

                /* RC：完整随机（用户手动切换种族时调用） */
                const RC = () => {
                    const r = I('i_rc').value;
                    RC_UI(r);
                    const c = DB[r] || DB["人族"];
                    P('i_rt', c.R); P('i_bd', c.B); P('i_lc', c.P); P('i_it', c.I);
                    I('i_ds').value = c.D[Math.floor(Math.random() * c.D.length)];
                    window._lastTier = window._lastTier || "common";
                    rollBodyMetrics(r, I('i_gd') ? I('i_gd').value : "男修");
                    rollSkills(r, window._lastTier);
                    gongfaSlots = rollGongfaSlots(r, window._lastTier);
                    shentongSlots = rollPracticeSlots(r, window._lastTier, generateOneShentong);
                    renderGongfaSlots();
                    renderShentongSlots();
                };


                /* 【多选与自动折叠逻辑 + 延迟渲染关系栏】 */
                window.SelComp = (el, idx, compRace) => {
                    const mapKey = compRace + '_' + idx;
                    if (el.classList.contains('active')) {
                        el.classList.remove('active');
                        selectedComps.delete(mapKey);

                        const relBar = el.querySelector('.rel-bar');
                        if (relBar) relBar.remove();

                        const tag = el.querySelector('.chosen-rel-tag');
                        if (tag) tag.remove();
                    } else {
                        el.classList.add('active');

                        const defaultRel = DB.Global.Rel.R[0];
                        selectedComps.set(mapKey, { comp: DB[compRace].C[idx], rel: defaultRel });

                        const tag = el.querySelector('.chosen-rel-tag');
                        if (tag) tag.remove();

                        /* 延迟渲染：仅在展开时注入关系选择栏 */
                        let relBar = el.querySelector('.rel-bar');
                        if (!relBar) {
                            relBar = document.createElement('div');
                            relBar.className = 'rel-bar';
                            relBar.style.display = 'flex';

                            const catRow = document.createElement('div');
                            catRow.className = 'rel-cat-row';
                            REL_CATEGORIES.forEach((cat, ci) => {
                                const btn = document.createElement('div');
                                btn.className = 'rel-btn';
                                btn.dataset.catIdx = ci;
                                btn.dataset.compIdx = idx;
                                btn.dataset.compRace = compRace;
                                btn.textContent = cat.label;
                                catRow.appendChild(btn);
                            });

                            const subRow = document.createElement('div');
                            subRow.className = 'rel-sub-row';
                            subRow.dataset.comp = idx;

                            relBar.appendChild(catRow);
                            relBar.appendChild(subRow);

                            /* 关系栏事件委托 */
                            relBar.addEventListener('click', (e) => {
                                e.stopPropagation();
                                const catBtn = e.target.closest('.rel-btn[data-cat-idx]');
                                if (catBtn) {
                                    window.ToggleRelCat(e, catBtn, parseInt(catBtn.dataset.catIdx), parseInt(catBtn.dataset.compIdx), catBtn.dataset.compRace);
                                    return;
                                }
                                const relBtn = e.target.closest('.rel-btn[data-rel-key]');
                                if (relBtn) {
                                    window.SelRel(e, relBtn, relBtn.dataset.relKey, parseInt(relBtn.dataset.compIdx), relBtn.dataset.compRace);
                                }
                            });

                            el.appendChild(relBar);
                        } else {
                            relBar.style.display = 'flex';
                        }

                        el.querySelectorAll('.rel-btn').forEach(b => b.classList.remove('active'));
                        const firstRelBtn = el.querySelector('.rel-btn');
                        if (firstRelBtn) firstRelBtn.classList.add('active');
                    }
                    window.RenderSelectedSummary();
                };

                /* 二级关系分类：点击大类展开具体关系 */
                window.ToggleRelCat = (e, el, catIdx, compIdx, compRace) => {
                    e.stopPropagation();
                    const cat = REL_CATEGORIES[catIdx];
                    if (!cat) return;

                    /* 高亮当前分类 */
                    const catRow = el.parentElement;
                    catRow.querySelectorAll('.rel-btn').forEach(b => b.classList.remove('active'));
                    el.classList.add('active');

                    /* 渲染该分类下的具体关系 */
                    const subRow = catRow.parentElement.querySelector('.rel-sub-row[data-comp="' + compIdx + '"]');
                    if (!subRow) return;

                    const mapKey = compRace + '_' + compIdx;
                    const selectedRel = selectedComps.has(mapKey) ? selectedComps.get(mapKey).rel : null;

                    const filtered = DB.Global.Rel.R.filter(rl => cat.filter.includes(rl.v));
                    subRow.innerHTML = '';
                    filtered.forEach(rl => {
                        const btn = document.createElement('div');
                        btn.className = 'rel-btn' + (selectedRel && selectedRel.v === rl.v ? ' active' : '');
                        btn.dataset.relKey = rl.v;
                        btn.dataset.compIdx = compIdx;
                        btn.dataset.compRace = compRace;
                        btn.textContent = rl.n;
                        subRow.appendChild(btn);
                    });
                    subRow.style.display = 'flex';
                };

                window.SelRel = (e, el, key, compIdx, compRace) => {
                    e.stopPropagation();

                    const parentItem = el.closest('.comp-item');
                    if (parentItem) {
                        parentItem.querySelectorAll('.rel-btn').forEach(b => b.classList.remove('active'));
                    }
                    el.classList.add('active');

                    /* 记录该 NPC 最终选中的关系 */
                    const mapKey = compRace + '_' + compIdx;
                    const relObj = DB.Global.Rel.R.find(r => r.v === key);
                    if (selectedComps.has(mapKey)) {
                        selectedComps.get(mapKey).rel = relObj;
                    }

                    /* 自动折叠羁绊栏并打上标签 */
                    if (parentItem) {
                        const relBar = parentItem.querySelector('.rel-bar');
                        if (relBar) relBar.style.display = 'none';

                        let nameEl = parentItem.querySelector('.comp-name');
                        if (nameEl) {
                            let oldTag = nameEl.querySelector('.chosen-rel-tag');
                            if (oldTag) oldTag.remove();
                            const tag = document.createElement('span');
                            tag.className = 'chosen-rel-tag';
                            tag.textContent = '已选: ' + relObj.n;
                            nameEl.appendChild(tag);
                        }
                    }
                    window.RenderSelectedSummary();
                };
                /* ═══════════════════════════════════════
                    [跨种族羁绊汇总] 渲染已选NPC摘要 + 移除功能
                ═══════════════════════════════════════ */
                window.RenderSelectedSummary = () => {
                    const box = I('comp_selected_summary');
                    if (!box) return;
                    if (selectedComps.size === 0) { box.innerHTML = ''; return; }

                    let chips = '<div class="selected-summary" id="comp_summary_scroll">'
                        + '<div class="selected-summary-label">已缔结的宿命羁绊（' + selectedComps.size + '位）：</div>';
                    selectedComps.forEach((val, mapKey) => {
                        const raceName = esc(mapKey.split('_')[0] || '?');
                        const compName = esc(val.comp ? val.comp.n : '?');
                        const relName = esc(val.rel ? val.rel.n : '未定');
                        chips += '<div class="selected-chip">'
                            + '<span class="chip-race">[' + raceName + ']</span> '
                            + '<span>' + compName + '</span>'
                            + ' · <span class="chip-rel">' + relName + '</span>'
                            + '<span class="chip-remove" data-remove-key="' + esc(mapKey) + '" title="解除羁绊">✖</span>'
                            + '</div>';
                    });
                    chips += '</div><div class="scroll-track" id="comp_scroll_track"><div class="scroll-thumb" id="comp_scroll_thumb"></div></div>';
                    box.innerHTML = chips;

                    /* 移除按钮事件委托 */
                    box.addEventListener('click', (e) => {
                        const removeBtn = e.target.closest('.chip-remove[data-remove-key]');
                        if (removeBtn) {
                            e.stopPropagation();
                            window.RemoveComp(removeBtn.dataset.removeKey);
                        }
                    });

                    /* 绑定滚动进度条 */
                    const scrollEl = I('comp_summary_scroll');
                    const track = I('comp_scroll_track');
                    const thumb = I('comp_scroll_thumb');
                    if (!scrollEl || !track || !thumb) return;

                    let fadeTimer = null;
                    const updateThumb = () => {
                        const sh = scrollEl.scrollHeight;
                        const ch = scrollEl.clientHeight;
                        if (sh <= ch) { track.classList.remove('visible'); return; }
                        const ratio = ch / sh;
                        const thumbH = Math.max(ratio * ch, 16);
                        const scrollRatio = scrollEl.scrollTop / (sh - ch);
                        const thumbTop = scrollRatio * (ch - thumbH);
                        thumb.style.height = thumbH + 'px';
                        thumb.style.top = thumbTop + 'px';
                        track.classList.add('visible');
                        clearTimeout(fadeTimer);
                        fadeTimer = setTimeout(() => { track.classList.remove('visible'); }, 1500);
                    };

                    scrollEl.addEventListener('scroll', updateThumb, { passive: true });
                    /* 初始检测一次：内容是否已超出 */
                    requestAnimationFrame(updateThumb);
                };


                window.RemoveComp = (mapKey) => {
                    selectedComps.delete(mapKey);
                    const compRace = I('i_comp_rc') ? I('i_comp_rc').value : "人族";
                    const prefix = mapKey.split('_')[0];
                    const idx = mapKey.split('_')[1];

                    if (prefix === compRace) {
                        const card = I('comp_root').querySelector('.comp-item[data-idx="' + idx + '"]');
                        if (card) {
                            card.classList.remove('active');
                            const relBar = card.querySelector('.rel-bar');
                            if (relBar) relBar.remove();
                            const tag = card.querySelector('.chosen-rel-tag');
                            if (tag) tag.remove();
                        }
                    }
                    window.RenderSelectedSummary();
                };

                /* ══════════════════════════════════
                   [身高体重] 种族性别联动随机
                ══════════════════════════════════ */
                const rollBodyMetrics = (race, gender) => {
                    const pool = BODY_METRICS[race] || BODY_METRICS["人族"];
                    const g = gender === "混沌"
                        ? {
                            hMin: Math.round((pool.m.hMin + pool.f.hMin) / 2),
                            hMax: Math.round((pool.m.hMax + pool.f.hMax) / 2),
                            wMin: Math.round((pool.m.wMin + pool.f.wMin) / 2),
                            wMax: Math.round((pool.m.wMax + pool.f.wMax) / 2)
                        }
                        : (gender === "男修" ? pool.m : pool.f);
                    const gauss = () => (Math.random() + Math.random() + Math.random()) / 3;
                    const h = Math.round(g.hMin + gauss() * (g.hMax - g.hMin));
                    const w = Math.round(g.wMin + gauss() * (g.wMax - g.wMin));
                    if (I('i_ht')) I('i_ht').value = h;
                    if (I('i_wt')) I('i_wt').value = w;
                };

                /* ══════════════════════════════════
                   [技艺五行] 渲染 + 事件
                ══════════════════════════════════ */
                window.RenderSkills = () => {
                    const panel = I('skill_panel');
                    if (!panel) return;
                    panel.innerHTML = '';
                    const race = I('i_rc') ? I('i_rc').value : "人族";
                    const level = I('i_cl') ? I('i_cl').value : "";
                    const tIndex = getCultivationTierIndex(race, level);

                    SKILL_NAMES.forEach((name, si) => {
                        const row = document.createElement('div');
                        row.className = 'skill-row';
                        const nameEl = document.createElement('div');
                        nameEl.className = 'skill-name';
                        nameEl.textContent = name;
                        const levelBox = document.createElement('div');
                        levelBox.className = 'skill-level';

                        const cap = getSkillCap(name, tIndex);
                        const curLv = Math.min(skillLevels[name] || 0, cap);
                        skillLevels[name] = curLv;

                        const lvList = PROFESSION_LEVELS[name];
                        lvList.forEach((lv, li) => {
                            const dot = document.createElement('div');
                            const isLocked = li > cap;
                            dot.className = 'skill-dot' + (li === curLv ? ' active' : '') + (isLocked ? ' locked' : '');
                            dot.textContent = lv;
                            dot.dataset.skill = name;
                            dot.dataset.lvIdx = li;
                            if (isLocked) {
                                dot.style.opacity = '0.45';
                                dot.style.cursor = 'not-allowed';
                                dot.title = "修为等阶不足，无法晋升此等阶";
                            }
                            levelBox.appendChild(dot);
                        });
                        row.appendChild(nameEl);
                        row.appendChild(levelBox);
                        panel.appendChild(row);
                    });
                };

                I('skill_panel').addEventListener('click', (e) => {
                    const dot = e.target.closest('.skill-dot');
                    if (!dot) return;
                    if (dot.classList.contains('locked')) return;
                    const sk = dot.dataset.skill;
                    const li = parseInt(dot.dataset.lvIdx, 10);
                    skillLevels[sk] = li;
                    const row = dot.parentElement;
                    row.querySelectorAll('.skill-dot').forEach((d, i) => {
                        d.classList.toggle('active', i === li);
                    });
                    U();
                });

                const rollSkills = (race, tier, highBias = null) => {
                    const bonus = SKILL_RACE_BONUS[race] || SKILL_RACE_BONUS["人族"];

                    const level = I('i_cl') ? I('i_cl').value : "";
                    const tIndex = getCultivationTierIndex(race, level);

                    const tierMax = { "trash": 0, "common": 1, "elite": 2, "prodigy": 3, "anomaly": 4 };
                    const cap = tierMax[tier] !== undefined ? tierMax[tier] : 1;
                    SKILL_NAMES.forEach((name, si) => {
                        const b = bonus[si] || 0;
                        const ruleMax = Math.min(cap + (b > 1 ? 1 : 0), 4);
                        const finalCap = Math.min(ruleMax, getSkillCap(name, tIndex));
                        if (finalCap <= 0) {
                            skillLevels[name] = 0;
                            return;
                        }
                        if (highBias !== null && Math.random() < highBias) {
                            skillLevels[name] = finalCap;
                            return;
                        }
                        skillLevels[name] = Math.floor(Math.random() * (finalCap + 1));
                    });
                    window.RenderSkills();
                };

                /* ══════════════════════════════════
                   [功法&神通] 组合随机生成 + 槽位管理
                ══════════════════════════════════ */
                const pick = arr => arr[Math.floor(Math.random() * arr.length)];

                const getCultivationTierIndex = (race, levelName) => {
                    const levels = RACE_LEVELS[race] || RACE_LEVELS["人族"];
                    const idx = levels.indexOf(levelName || "");
                    return idx >= 0 ? idx : 1;
                };

                const resolvePracticeRank = (race, levelName, tier) => {
                    if (Math.random() < SPECIAL_IMMORTAL_RATE) return "仙";
                    const tIndex = getCultivationTierIndex(race, levelName || (I('i_cl') ? I('i_cl').value : ""));
                    const maxRankIdx = getPracticeMaxRankIdx(tIndex);
                    const chosenIdx = Math.floor(Math.random() * (maxRankIdx + 1));
                    return MORTAL_PRACTICE_RANKS[chosenIdx];
                };

                const syncPracticeRanksToCultivation = () => {
                    const race = I('i_rc') ? I('i_rc').value : "人族";
                    const level = I('i_cl') ? I('i_cl').value : "";
                    const tIndex = getCultivationTierIndex(race, level);
                    const maxRankIdx = getPracticeMaxRankIdx(tIndex);
                    const maxRank = MORTAL_PRACTICE_RANKS[maxRankIdx];

                    const clampRank = (currentRank) => {
                        if (IMMORTAL_PRACTICE_RANKS.includes(currentRank)) return currentRank;
                        const curIdx = MORTAL_PRACTICE_RANKS.indexOf(currentRank);
                        if (curIdx < 0) return maxRank;
                        if (curIdx > maxRankIdx) {
                            return maxRank;
                        }
                        return currentRank;
                    };

                    gongfaSlots = gongfaSlots.map(gf => ({ ...gf, rank: clampRank(gf.rank) }));
                    shentongSlots = shentongSlots.map(st => ({ ...st, rank: clampRank(st.rank) }));
                    renderGongfaSlots();
                    renderShentongSlots();
                };

                const rollGongfaLayer = (tier) => {
                    const maxIdx = { "trash": 2, "common": 3, "elite": 5, "prodigy": 7, "anomaly": 10 };
                    const cap = maxIdx[tier] || 3;
                    return GONGFA_LAYERS[Math.floor(Math.random() * Math.min(cap, GONGFA_LAYERS.length))];
                };

                const rollShentongProf = (tier) => {
                    const maxIdx = { "trash": 1, "common": 2, "elite": 3, "prodigy": 4, "anomaly": 5 };
                    const cap = maxIdx[tier] || 2;
                    return SHENTONG_PROF[Math.floor(Math.random() * Math.min(cap, SHENTONG_PROF.length))];
                };

                const pickRankEffect = (rank, tier, isGongfa) => {
                    const group = isGongfa ? GONGFA_EFFECTS_BY_RANK[rank] : SHENTONG_EFFECTS_BY_RANK[rank];
                    if (!group) return null;
                    const goodRate = { "trash": 0.08, "common": 0.18, "elite": 0.35, "prodigy": 0.55, "anomaly": 0.65 };
                    const type = Math.random() < (goodRate[tier] ?? 0.2) ? "good" : "normal";
                    return pick(group[type]);
                };

                const blendEffect = (baseEffect, rank, tier, isGongfa) => {
                    const rankEffect = pickRankEffect(rank, tier, isGongfa);
                    if (!rankEffect) return baseEffect;
                    return rankEffect + "；" + baseEffect;
                };

                const pickPracticePool = (race, racePoolMap) => {
                    return racePoolMap[race] || racePoolMap["人族"];
                };

                const generateOneGongfa = (race, tier) => {
                    const rank = resolvePracticeRank(race, I('i_cl') ? I('i_cl').value : null, tier || "common");
                    if (rank === "仙") {
                        const joke = pick(GONGFA_JOKE_POOL);
                        return {
                            name: joke.name,
                            rank,
                            layer: rollGongfaLayer(tier || "common"),
                            effect: joke.effect
                        };
                    }
                    const pool = pickPracticePool(race, GONGFA_DB);
                    return {
                        name: pick(pool.prefix) + pick(pool.core) + pick(pool.suffix),
                        rank,
                        layer: rollGongfaLayer(tier || "common"),
                        effect: blendEffect(pick(pool.effects), rank, tier || "common", true)
                    };
                };

                const generateOneShentong = (race, tier) => {
                    const rank = resolvePracticeRank(race, I('i_cl') ? I('i_cl').value : null, tier || "common");
                    if (rank === "仙") {
                        const joke = pick(SHENTONG_JOKE_POOL);
                        return {
                            name: joke.name,
                            rank,
                            prof: rollShentongProf(tier || "common"),
                            effect: joke.effect
                        };
                    }
                    const pool = pickPracticePool(race, SHENTONG_DB);
                    return {
                        name: pick(pool.prefix) + pick(pool.core) + pick(pool.suffix),
                        rank,
                        prof: rollShentongProf(tier || "common"),
                        effect: blendEffect(pick(pool.effects), rank, tier || "common", false)
                    };
                };

                const rollPracticeSlots = (race, tier, generator) => {
                    const emptyRate = PRACTICE_EMPTY_RATE_BY_TIER[tier] ?? PRACTICE_EMPTY_RATE;
                    if (Math.random() < emptyRate) return [];
                    const countRoll = Math.random();
                    let count = 1;
                    if (tier === "anomaly" && countRoll > 0.65) count = 2;
                    else if ((tier === "prodigy" || tier === "elite") && countRoll > 0.82) count = 2;
                    const slots = [];
                    for (let i = 0; i < count; i++) slots.push(generator(race, tier));
                    return slots;
                };

                const rollGongfaSlots = (race, tier) => rollPracticeSlots(race, tier, generateOneGongfa).slice(0, 1);

                const pickByDestinyTier = (arr, t) => {
                    if (!arr || arr.length === 0) return null;
                    const len = arr.length;
                    const ranges = {
                        "trash": [0, Math.max(1, Math.floor(len * 0.2))],
                        "common": [Math.floor(len * 0.15), Math.max(Math.floor(len * 0.15) + 1, Math.floor(len * 0.5))],
                        "elite": [Math.floor(len * 0.4), Math.max(Math.floor(len * 0.4) + 1, Math.floor(len * 0.75))],
                        "prodigy": [Math.floor(len * 0.65), Math.max(Math.floor(len * 0.65) + 1, Math.floor(len * 0.9))],
                        "anomaly": [Math.floor(len * 0.8), len]
                    };
                    const range = ranges[t] || [0, len];
                    const idx = Math.min(range[0] + Math.floor(Math.random() * Math.max(1, range[1] - range[0])), len - 1);
                    return arr[idx];
                };

                const DIFFICULTY_RULES = {
                    easy: {
                        kicker: "温养命卷 · 天道暗骰",
                        title: "青云扶摇",
                        desc: "只可改写真名；境界锁在初阶至筑基，善缘与传承会明显偏向顺风开局。",
                        promptHint: "青云扶摇：T1-T3开局，带一至两段T1-T5低中阶善缘，必有当前境界内偏高技艺、一门主修功法、三门神通与明显正向造化；功法/神通常规品阶只以当前境界为随机上限，不保证等于上限，仙阶仅作为10%特殊仙法彩蛋按效果叙事。",
                        destinyTier: "prodigy",
                        levelRange: [1, 3],
                        relationCount: [1, 2],
                        relationTiers: ["T1", "T2", "T3", "T4", "T5"],
                        relationMood: "good",
                        practiceCount: 3,
                        gongfaCount: 1,
                        skillMode: "high",
                        itemMode: "good",
                        luckRange: [19, 31]
                    },
                    normal: {
                        kicker: "平衡命卷 · 天道暗骰",
                        title: "尘劫问道",
                        desc: "只可改写真名；资质与机缘有起有落，不会故意保送，也不会把路彻底堵死。",
                        promptHint: "尘劫问道：中性开局，境界、资质、外物与羁绊按常规暗骰波动，可有一两处小机缘，也可带一点麻烦；功法/神通常规品阶只以当前境界为随机上限，不保证等于上限，仙阶仅作为10%特殊仙法彩蛋按效果叙事。",
                        destinyTier: "elite",
                        levelRange: [0, 5],
                        relationCount: [0, 2],
                        relationTiers: ["T0", "T1", "T2", "T3", "T4", "T5"],
                        relationMood: "mixed",
                        practiceCount: null,
                        skillMode: "mixed",
                        itemMode: "mixed",
                        luckRange: [5, 24]
                    },
                    hard: {
                        kicker: "残烬命卷 · 天道暗骰",
                        title: "孤灯逆劫",
                        desc: "只可改写真名；必从最低阶起步，几乎没有可靠关系，没有功法神通和技艺，偶尔只剩荒诞物件傍身。",
                        promptHint: "孤灯逆劫：只能T1开局，零到一段T1关系，必无功法、神通与技艺，不给正向造化，可出现偏无厘头但不可靠的随身物；若后续手动随机功法/神通，常规品阶也只以当前境界为随机上限，不保证等于上限，仙阶仅作为10%特殊仙法彩蛋按效果叙事。",
                        destinyTier: "trash",
                        levelRange: [1, 1],
                        relationCount: [0, 1],
                        relationTiers: ["T1"],
                        relationMood: "hard",
                        practiceCount: 0,
                        skillMode: "none",
                        itemMode: "absurd",
                        luckRange: [0, 5]
                    }
                };

                let currentQuickMode = null;
                let customInitialized = false;

                const rollRaceWeighted = () => {
                    const r = Math.random();
                    if (r > .92) return "灵族";
                    if (r > .84) return "魔族";
                    if (r > .76) return "鬼族";
                    if (r > .64) return "半妖";
                    if (r > .40) return "妖族";
                    return "人族";
                };

                const rollGenderWeighted = () => {
                    const r = Math.random();
                    if (r < 0.03) return "混沌";
                    return r < 0.515 ? "男修" : "女修";
                };

                const rollQuickName = (race, gender) => {
                    const surnames = {
                        "人族": ["沈", "谢", "裴", "陆", "姜", "顾", "楚", "叶", "秦", "苏", "凌", "萧"],
                        "妖族": ["青丘", "涂山", "玄", "白", "赤", "灵", "狐", "蛟"],
                        "半妖": ["沈", "陆", "青", "玄", "白", "涂山", "顾", "叶"],
                        "鬼族": ["忘川", "九幽", "冥", "夜", "寒", "魂", "薄", "泉"],
                        "魔族": ["无间", "修罗", "厉", "渊", "罗", "煞", "堕", "劫"],
                        "灵族": ["太初", "鸿蒙", "灵", "玉", "璃", "霁", "岚", "泉"]
                    };
                    const male = ["归尘", "长渊", "既白", "临渊", "问剑", "惊蛰", "逐北", "知还", "饮冰", "坠星"];
                    const female = ["惊鸿", "折枝", "岁宁", "清宵", "知秋", "予安", "扶摇", "冷香", "漱玉", "碎月"];
                    const given = gender === "男修" ? male : (gender === "女修" ? female : (Math.random() > 0.5 ? male : female));
                    return pick(surnames[race] || surnames["人族"]) + pick(given);
                };

                const setSimpleValue = (id, value) => {
                    const el = I(id);
                    if (el) el.value = value;
                    const disp = I('disp_' + id);
                    if (disp) disp.innerText = value;
                };

                const pickLuckByRange = (range) => {
                    const arr = DB.Global.Luck;
                    const lo = Math.max(0, range[0]);
                    const hi = Math.min(arr.length, range[1]);
                    return arr[lo + Math.floor(Math.random() * Math.max(1, hi - lo))];
                };

                const pickAbsurdItem = (items) => {
                    const pool = (items || []).filter(item => {
                        const text = typeof item === 'string' ? item : (item.n || '');
                        return /母猪|高仿|没电|没有子弹|滑稽|黑锅|粪便|催债|招蚊子|敲不响|木制|破碗|打狗棒|草鞋|打不开/.test(text);
                    });
                    return pool.length ? pick(pool) : pick((items || []).slice(0, Math.max(1, Math.ceil((items || []).length * 0.2))));
                };

                const setSkillsForRule = (rule, race) => {
                    if (rule.skillMode === "none") {
                        SKILL_NAMES.forEach(name => { skillLevels[name] = 0; });
                        return;
                    }
                    rollSkills(race, rule.destinyTier || "common", rule.skillMode === "high" ? 0.75 : null);
                };

                const getCompTier = (comp) => {
                    const m = comp && comp.d ? comp.d.match(/\((T\d|EX|S)\)$/) : null;
                    return m ? m[1] : "T1";
                };

                const pickRelationForRule = (mood) => {
                    const rels = DB.Global.Rel.R;
                    const good = ["sponsor", "guide", "senior_brother", "senior_sister", "confidant", "childhood_friend", "best_friend", "life_saver", "guardian", "follower"];
                    const hard = ["stranger", "passerby", "competitor", "debtor", "scapegoat", "captive", "prisoner", "experiment"];
                    const keys = mood === "good" ? good : (mood === "hard" ? hard : null);
                    const pool = keys ? rels.filter(r => keys.includes(r.v)) : rels;
                    return pick(pool.length ? pool : rels);
                };

                const rollRelationsForRule = (rule, race) => {
                    selectedComps.clear();
                    const count = rule.relationCount[0] + Math.floor(Math.random() * (rule.relationCount[1] - rule.relationCount[0] + 1));
                    if (count <= 0) return;
                    const compPool = (DB[race].C || []).map((comp, idx) => ({ comp, idx, tier: getCompTier(comp) })).filter(x => rule.relationTiers.includes(x.tier));
                    const used = new Set();
                    for (let i = 0; i < count && compPool.length > 0; i++) {
                        let picked;
                        let guard = 0;
                        do { picked = pick(compPool); guard++; } while (used.has(picked.idx) && guard < 20);
                        if (!picked || used.has(picked.idx)) break;
                        used.add(picked.idx);
                        selectedComps.set(race + '_' + picked.idx, { comp: picked.comp, rel: pickRelationForRule(rule.relationMood) });
                    }
                };

                const fillQuickFields = (mode) => {
                    const rule = DIFFICULTY_RULES[mode];
                    if (!rule) return null;
                    currentQuickMode = mode;
                    const race = rollRaceWeighted();
                    const gender = rollGenderWeighted();
                    const c = DB[race] || DB["人族"];
                    const levels = RACE_LEVELS[race] || RACE_LEVELS["人族"];
                    const levelIdx = rule.levelRange[0] + Math.floor(Math.random() * Math.max(1, rule.levelRange[1] - rule.levelRange[0] + 1));
                    const level = levels[Math.min(levelIdx, levels.length - 1)];
                    const age = mode === "hard" ? (12 + Math.floor(Math.random() * 9)) : (14 + Math.floor(Math.random() * (mode === "easy" ? 90 : 220)));
                    const name = rollQuickName(race, gender);

                    setSimpleValue('i_rc', race);
                    setSimpleValue('i_gd', gender);
                    setSimpleValue('i_cl', level);
                    if (I('l_rt')) I('l_rt').innerText = c.L;
                    if (I('i_ag')) I('i_ag').value = age;
                    if (I('v_ag')) I('v_ag').innerText = age;
                    if (I('quick_nm')) I('quick_nm').value = name;
                    if (I('i_nm')) I('i_nm').value = name;

                    P('i_rt', [pickByDestinyTier(c.R, rule.destinyTier)]);
                    P('i_bd', [pickByDestinyTier(c.B, rule.destinyTier)]);
                    P('i_lc', [pickByDestinyTier(c.P, rule.destinyTier)]);
                    P('i_lk', [pickLuckByRange(rule.luckRange)]);
                    if (rule.itemMode === "absurd") P('i_it', [pickAbsurdItem(c.I)]);
                    else P('i_it', [pickByDestinyTier(c.I, rule.itemMode === "good" ? "prodigy" : rule.destinyTier)]);

                    const desc = mode === "hard"
                        ? pick(c.D || DB["人族"].D) + " 只是此身命盘黯淡，开局除了一点不合时宜的荒唐物件，几乎没有可倚仗之处。"
                        : pick(c.D || DB["人族"].D);
                    if (I('i_ds')) I('i_ds').value = desc;

                    rollBodyMetrics(race, gender);
                    setSkillsForRule(rule, race);
                    if (rule.practiceCount === 0) {
                        gongfaSlots = [];
                        shentongSlots = [];
                    } else if (rule.practiceCount) {
                        const gongfaCount = Math.min(rule.gongfaCount ?? rule.practiceCount, 1);
                        gongfaSlots = Array.from({ length: gongfaCount }, () => generateOneGongfa(race, rule.destinyTier));
                        shentongSlots = Array.from({ length: rule.practiceCount }, () => generateOneShentong(race, rule.destinyTier));
                    } else {
                        gongfaSlots = rollGongfaSlots(race, rule.destinyTier);
                        shentongSlots = rollPracticeSlots(race, rule.destinyTier, generateOneShentong);
                    }
                    rollRelationsForRule(rule, race);
                    return { rule, race, gender, level, age, name };
                };

                const renderQuickPreview = () => {
                    const box = I('quick_preview');
                    const rule = DIFFICULTY_RULES[currentQuickMode];
                    if (!box || !rule) return;
                    const skillTxt = SKILL_NAMES.map(name => `${name}${PROFESSION_LEVELS[name][skillLevels[name] || 0]}`).join(' / ');
                    const relTxt = selectedComps.size > 0 ? Array.from(selectedComps.values()).map(v => `${v.comp.n} · ${v.rel.n}`).join('；') : '无';
                    const gfTxt = gongfaSlots.length > 0 ? `${gongfaSlots.length}门功法 / ${shentongSlots.length}门神通` : (shentongSlots.length > 0 ? `无功法 / ${shentongSlots.length}门神通` : '无功法神通');
                    box.innerHTML = '<div class="quick-line"><strong>命轨</strong>：' + esc(rule.title) + '</div>'
                        + '<div class="quick-line"><strong>血脉</strong>：' + esc(I('i_rc').value) + ' · ' + esc(I('i_gd').value) + ' · ' + esc(I('i_ag').value) + '岁</div>'
                        + '<div class="quick-line"><strong>境界</strong>：' + esc(I('i_cl').value) + '</div>'
                        + '<div class="quick-line"><strong>天命</strong>：' + esc(I('i_lk').value) + '</div>'
                        + '<div class="quick-line"><strong>造化</strong>：' + esc(I('i_rt').value) + ' / ' + esc(I('i_bd').value) + '</div>'
                        + '<div class="quick-line"><strong>传承</strong>：' + esc(gfTxt) + '</div>'
                        + '<div class="quick-line"><strong>技艺</strong>：' + esc(skillTxt) + '</div>'
                        + '<div class="quick-line"><strong>羁绊</strong>：' + esc(relTxt) + '</div>';
                };

                const renderGongfaSlots = () => {
                    const container = I('gf_slots');
                    if (!container) return;
                    container.innerHTML = '';
                    gongfaSlots.forEach((gf, idx) => {
                        const card = document.createElement('div');
                        card.className = 'gf-card';
                        card.innerHTML = '<div class="gf-card-header">'
                            + '<span class="gf-card-name">' + esc(gf.name) + '</span>'
                            + '<span class="gf-card-rank">' + esc(gf.rank) + '阶</span>'
                            + '</div>'
                            + '<div class="gf-card-detail">效果：' + esc(gf.effect) + '</div>'
                            + '<div class="gf-card-meta">修炼进度：' + esc(gf.layer) + '</div>'
                            + '<div class="gf-card-actions">'
                            + '<div class="gf-card-btn" data-gf-rand="' + idx + '" title="重随">⟳</div>'
                            + '<div class="gf-card-btn" data-gf-del="' + idx + '" title="删除">✖</div>'
                            + '</div>';
                        container.appendChild(card);
                    });
                    const addBtn = I('gf_add');
                    if (addBtn) addBtn.classList.toggle('disabled', gongfaSlots.length >= 1);
                };

                const renderShentongSlots = () => {
                    const container = I('st_slots');
                    if (!container) return;
                    container.innerHTML = '';
                    shentongSlots.forEach((st, idx) => {
                        const card = document.createElement('div');
                        card.className = 'gf-card';
                        card.innerHTML = '<div class="gf-card-header">'
                            + '<span class="gf-card-name">' + esc(st.name) + '</span>'
                            + '<span class="gf-card-rank">' + esc(st.rank) + '阶</span>'
                            + '</div>'
                            + '<div class="gf-card-detail">效果：' + esc(st.effect) + '</div>'
                            + '<div class="gf-card-meta">熟练度：' + esc(st.prof) + '</div>'
                            + '<div class="gf-card-actions">'
                            + '<div class="gf-card-btn" data-st-rand="' + idx + '" title="重随">⟳</div>'
                            + '<div class="gf-card-btn" data-st-del="' + idx + '" title="删除">✖</div>'
                            + '</div>';
                        container.appendChild(card);
                    });
                    const addBtn = I('st_add');
                    if (addBtn) addBtn.classList.toggle('disabled', shentongSlots.length >= 3);
                };

                /* 功法区事件委托 */
                I('gf_section').addEventListener('click', (e) => {
                    const race = I('i_rc') ? I('i_rc').value : "人族";
                    const randBtn = e.target.closest('[data-gf-rand]');
                    if (randBtn) {
                        const idx = parseInt(randBtn.dataset.gfRand, 10);
                        gongfaSlots[idx] = generateOneGongfa(race, window._lastTier || "common");
                        renderGongfaSlots();
                        return;
                    }
                    const delBtn = e.target.closest('[data-gf-del]');
                    if (delBtn) {
                        gongfaSlots.splice(parseInt(delBtn.dataset.gfDel, 10), 1);
                        renderGongfaSlots();
                        return;
                    }
                    if (e.target.id === 'gf_add' || e.target.closest('#gf_add')) {
                        if (gongfaSlots.length < 1) {
