        @keyframes tier-breath-cyan { 0% { box-shadow: 0 0 25px rgba(52, 152, 219, 0.2), inset 0 0 15px rgba(52, 152, 219, 0.1); } 100% { box-shadow: 0 0 50px rgba(52, 152, 219, 0.5), inset 0 0 30px rgba(52, 152, 219, 0.3); border-color: rgba(52, 152, 219, 0.8); } }
        .tier-11 { border: 2px solid var(--gold); background: linear-gradient(135deg, rgba(255, 253, 245, 0.98), rgba(255, 225, 100, 0.2)), var(--bg-paper); box-shadow: 0 0 40px rgba(255, 215, 0, 0.4), inset 0 0 30px rgba(255, 215, 0, 0.25); }
        .tier-12 { border: 2px solid transparent; background: linear-gradient(135deg, rgba(255, 250, 240, 1), rgba(250, 230, 225, 1)) padding-box, linear-gradient(135deg, var(--gold), var(--vermilion), var(--gold)) border-box; box-shadow: 0 0 45px rgba(255, 215, 0, 0.6), inset 0 0 35px rgba(142, 40, 31, 0.2); animation: tier-breath-gold 2.5s infinite alternate; }
        .tier-13 { border: 2px solid transparent; background: linear-gradient(135deg, rgba(255, 250, 255, 1), rgba(240, 230, 255, 1)) padding-box, linear-gradient(45deg, #ff5e62, #ff9966, #ff00ff, #00ffff) border-box; box-shadow: 0 0 60px rgba(180, 100, 255, 0.6), inset 0 0 40px rgba(255, 255, 255, 0.8); animation: tier-rainbow-breath 4s infinite linear; }

        @keyframes tier-breath-red {
