        .zx-card { position: relative; overflow: hidden; transition: all 0.5s cubic-bezier(0.16, 1, 0.3, 1); }
        .zx-decor { position: absolute; pointer-events: none; z-index: 1; }

        .zx-tier-0 { border-color: rgba(130, 142, 144, 0.4); background: linear-gradient(180deg, rgba(240, 237, 229, 0.9) 0%, rgba(220, 215, 205, 0.95) 100%); box-shadow: inset 0 0 10px rgba(0, 0, 0, 0.05); }
        .zx-tier-1 { border-color: rgba(179, 139, 77, 0.4); background: linear-gradient(180deg, rgba(255, 255, 255, 0.95) 0%, rgba(245, 240, 230, 0.95) 100%); box-shadow: 0 0 10px rgba(179, 139, 77, 0.1), inset 0 0 8px rgba(179, 139, 77, 0.1); }
        .zx-tier-2 { border: 1px solid var(--cyan); background: linear-gradient(180deg, rgba(255, 255, 255, 0.98) 0%, rgba(235, 245, 245, 0.95) 100%); box-shadow: 0 0 15px rgba(59, 95, 96, 0.2), inset 0 0 10px rgba(59, 95, 96, 0.15); }
        .zx-tier-3 { border: 2px solid var(--gold); background: linear-gradient(180deg, rgba(255, 253, 248, 0.98) 0%, rgba(250, 240, 220, 0.95) 100%); box-shadow: 0 0 20px rgba(179, 139, 77, 0.3), inset 0 0 15px rgba(179, 139, 77, 0.2); }
        .zx-tier-4 { border: 2px double var(--purple); background: linear-gradient(180deg, rgba(255, 250, 255, 0.98) 0%, rgba(240, 230, 245, 0.95) 100%); box-shadow: 0 0 25px rgba(76, 54, 84, 0.35), inset 0 0 20px rgba(76, 54, 84, 0.2); }
        .zx-tier-5 { border: 2px dashed var(--vermilion); background: linear-gradient(180deg, rgba(255, 250, 248, 0.98) 0%, rgba(250, 225, 220, 0.95) 100%); box-shadow: 0 0 35px rgba(142, 40, 31, 0.4), inset 0 0 25px rgba(142, 40, 31, 0.25); animation: zx-breath-red 3s infinite alternate; }
        .zx-tier-6 { border: 2px solid transparent; background: linear-gradient(180deg, rgba(255, 255, 255, 0.98) 0%, rgba(255, 250, 230, 0.9) 100%) padding-box, linear-gradient(135deg, var(--gold), var(--cyan), var(--gold)) border-box; box-shadow: 0 0 45px rgba(179, 139, 77, 0.6), inset 0 0 30px rgba(255, 255, 255, 0.8); animation: zx-breath-gold 2.5s infinite alternate; }
        .zx-tier-7 { border: 2px solid transparent; background: linear-gradient(180deg, rgba(255, 255, 255, 0.98) 0%, rgba(255, 240, 245, 0.85) 100%) padding-box, linear-gradient(45deg, var(--vermilion), var(--gold), var(--cyan), var(--purple)) border-box; box-shadow: 0 0 60px rgba(255, 100, 100, 0.5), inset 0 0 40px rgba(255, 215, 0, 0.5); animation: tier-rainbow-breath 5s infinite linear; }

        @keyframes zx-breath-red {
            0% { box-shadow: 0 0 20px rgba(142, 40, 31, 0.3), inset 0 0 15px rgba(142, 40, 31, 0.2); }
            100% { box-shadow: 0 0 45px rgba(142, 40, 31, 0.6), inset 0 0 35px rgba(142, 40, 31, 0.4); border-color: var(--vermilion); }
        }

        @keyframes zx-breath-gold {
            0% { box-shadow: 0 0 30px rgba(179, 139, 77, 0.4), inset 0 0 20px rgba(255, 255, 255, 0.5); }
            100% { box-shadow: 0 0 60px rgba(255, 215, 0, 0.7), inset 0 0 40px rgba(255, 255, 255, 0.9); }
        }

        /* ===== 纯几何无字阵法体系 ===== */
        .wrapper { transition: background-color 1.2s, box-shadow 1.2s ease-in-out; }

        .wrapper.app-tier-0,
        .wrapper.app-tier-1 { box-shadow: 0 0 30px rgba(0, 0, 0, 0.3); }

        .wrapper.app-tier-2 { animation: ui-breath-t2 4s infinite alternate ease-in-out !important; }

        .wrapper.app-tier-3,
        .wrapper.app-tier-4,
        .wrapper.app-tier-5 { animation: ui-breath-t3 3s infinite alternate !important; }

        .wrapper.app-tier-3::before, .wrapper.app-tier-3::after,
        .wrapper.app-tier-4::before, .wrapper.app-tier-4::after,
        .wrapper.app-tier-5::before, .wrapper.app-tier-5::after {
            width: 180px; height: 180px;
            border: 1px dashed rgba(179, 139, 77, 0.5);
            outline: 1px solid rgba(179, 139, 77, 0.2);
            outline-offset: -12px;
            background: radial-gradient(circle, transparent 55%, rgba(179, 139, 77, 0.1) 56%, transparent 58%);
            animation: ui-spin 20s linear infinite;
        }

        .wrapper.app-tier-6 { animation: ui-breath-t6 3s infinite alternate !important; }
        .wrapper.app-tier-7 { animation: ui-breath-t7 3s infinite alternate !important; }
        .wrapper.app-tier-8 { animation: ui-breath-red 3s infinite alternate !important; }

        .wrapper.app-tier-6::before, .wrapper.app-tier-6::after,
        .wrapper.app-tier-7::before, .wrapper.app-tier-7::after,
        .wrapper.app-tier-8::before, .wrapper.app-tier-8::after {
            width: 260px; height: 260px;
            border: 2px solid rgba(179, 139, 77, 0.3);
            outline: 2px dashed rgba(179, 139, 77, 0.4);
            outline-offset: -20px;
            background:
                repeating-conic-gradient(from 0deg, transparent 0 10deg, rgba(179, 139, 77, 0.15) 10deg 11deg, transparent 11deg 45deg),
                radial-gradient(circle, transparent 40%, rgba(179, 139, 77, 0.2) 41%, transparent 43%);
            animation: ui-spin 30s linear infinite reverse;
        }

        .wrapper.app-tier-8::before, .wrapper.app-tier-8::after {
            border-color: rgba(142, 40, 31, 0.4);
            outline-color: rgba(142, 40, 31, 0.5);
            background:
                repeating-conic-gradient(from 0deg, transparent 0 15deg, rgba(142, 40, 31, 0.2) 15deg 16deg, transparent 16deg 30deg),
                radial-gradient(circle, transparent 40%, rgba(142, 40, 31, 0.25) 41%, transparent 43%);
        }

        .wrapper.app-tier-9, .wrapper.app-tier-10 {
            animation: ui-breath-cyan 3.5s infinite alternate !important;
            background-color: rgba(250, 253, 255, 0.95) !important;
        }

        .wrapper.app-tier-9::before, .wrapper.app-tier-9::after,
        .wrapper.app-tier-10::before, .wrapper.app-tier-10::after {
            width: 320px; height: 320px;
            border: 1px solid rgba(52, 152, 219, 0.4);
            outline: 1px dotted rgba(52, 152, 219, 0.6);
            outline-offset: 8px;
            background:
                repeating-conic-gradient(from 0deg, rgba(52, 152, 219, 0.15) 0 1deg, transparent 1deg 6deg),
                radial-gradient(circle, transparent 35%, rgba(52, 152, 219, 0.3) 36%, transparent 38%, transparent 50%, rgba(52, 152, 219, 0.15) 51%, transparent 53%);
            animation: ui-spin 25s linear infinite;
            -webkit-mask-image: radial-gradient(circle, black 40%, transparent 70%);
        }

        .wrapper.app-tier-11, .wrapper.app-tier-12 {
            animation: ui-breath-gold 3s infinite alternate !important;
            background-color: rgba(255, 253, 245, 0.96) !important;
        }

        .wrapper.app-tier-13 {
            animation: ui-rainbow-breath 5s infinite linear !important;
            background-color: rgba(255, 255, 255, 0.98) !important;
            overflow: hidden;
        }

        .wrapper.app-tier-11::before, .wrapper.app-tier-11::after,
        .wrapper.app-tier-12::before, .wrapper.app-tier-12::after,
        .wrapper.app-tier-13::before, .wrapper.app-tier-13::after {
            width: 450px; height: 450px;
            top: -120px; left: -120px;
            border: 2px dashed rgba(255, 215, 0, 0.5);
            outline: 3px double rgba(180, 100, 255, 0.4);
            outline-offset: -30px;
            background:
                repeating-conic-gradient(from 0deg, rgba(255, 215, 0, 0.15) 0 2deg, transparent 2deg 15deg, rgba(180, 100, 255, 0.1) 15deg 16deg, transparent 16deg 30deg),
                radial-gradient(circle, transparent 40%, rgba(255, 215, 0, 0.3) 41%, transparent 43%, transparent 58%, rgba(180, 100, 255, 0.25) 59%, transparent 61%);
            animation: ui-spin 40s linear infinite reverse;
            -webkit-mask-image: radial-gradient(circle, black 30%, transparent 65%);
        }

        .wrapper.app-tier-11::after, .wrapper.app-tier-12::after, .wrapper.app-tier-13::after {
            bottom: -120px; right: -120px; top: auto; left: auto;
        }

        @keyframes ui-spin { 100% { transform: rotate(360deg); } }
        @keyframes ui-breath-t2 {
            0% { box-shadow: 0 0 40px rgba(59, 95, 96, 0.1), inset 0 0 20px rgba(59, 95, 96, 0.1); }
            100% { box-shadow: 0 0 60px rgba(59, 95, 96, 0.3), inset 0 0 40px rgba(59, 95, 96, 0.2); }
        }
        @keyframes ui-breath-t3 {
            0% { box-shadow: 0 0 50px rgba(179, 139, 77, 0.15), inset 0 0 30px rgba(179, 139, 77, 0.1); }
            100% { box-shadow: 0 0 80px rgba(179, 139, 77, 0.4), inset 0 0 50px rgba(179, 139, 77, 0.25); }
        }
        @keyframes ui-breath-t6 {
            0% { box-shadow: 0 0 60px rgba(179, 139, 77, 0.25), inset 0 0 40px rgba(179, 139, 77, 0.2); }
            100% { box-shadow: 0 0 100px rgba(179, 139, 77, 0.6), inset 0 0 70px rgba(179, 139, 77, 0.4); }
        }
        @keyframes ui-breath-t7 {
            0% { box-shadow: 0 0 80px rgba(179, 139, 77, 0.4), inset 0 0 50px rgba(179, 139, 77, 0.3); }
            100% { box-shadow: 0 0 120px var(--gold), inset 0 0 80px rgba(179, 139, 77, 0.6); }
        }
        @keyframes ui-breath-red {
            0% { box-shadow: 0 0 80px rgba(142, 40, 31, 0.3), inset 0 0 50px rgba(142, 40, 31, 0.2); }
            100% { box-shadow: 0 0 140px rgba(142, 40, 31, 0.8), inset 0 0 90px rgba(142, 40, 31, 0.5); }
        }
        @keyframes ui-breath-cyan {
            0% { box-shadow: 0 0 80px rgba(174, 214, 241, 0.4), inset 0 0 60px rgba(255, 255, 255, 0.6); }
            100% { box-shadow: 0 0 140px rgba(52, 152, 219, 0.7), inset 0 0 100px rgba(255, 255, 255, 0.9); }
        }
        @keyframes ui-breath-gold {
            0% { box-shadow: 0 0 90px rgba(255, 215, 0, 0.4), inset 0 0 70px rgba(179, 139, 77, 0.3); }
            100% { box-shadow: 0 0 160px rgba(255, 215, 0, 0.9), inset 0 0 120px rgba(255, 215, 0, 0.6); }
        }
        @keyframes ui-rainbow-breath {
            0% { box-shadow: 0 0 120px rgba(180, 100, 255, 0.5), inset 0 0 80px rgba(255, 255, 255, 0.8); filter: hue-rotate(0deg); }
            50% { box-shadow: 0 0 180px rgba(0, 255, 255, 0.8), inset 0 0 120px #fff; }
            100% { box-shadow: 0 0 120px rgba(180, 100, 255, 0.5), inset 0 0 80px rgba(255, 255, 255, 0.8); filter: hue-rotate(360deg); }
        }

        .tier-dao-text {
            background: linear-gradient(90deg, #b38b4d, #5c4366, #4a6f70, #8e281f, #b38b4d);
            background-size: 200% auto;
            -webkit-background-clip: text;
            -webkit-text-fill-color: transparent;
            animation: introverted-flow 6s linear infinite;
            font-weight: bold;
        }

        .tier-di-text {
            color: #111418;
            text-shadow: 0 0 4px rgba(142, 40, 31, 0.4);
            font-weight: bold;
        }

        .tier-tag {
            font-size: 0.6rem;
            padding: 0 4px;
            border-radius: 2px;
            margin-left: 6px;
            vertical-align: text-bottom;
            -webkit-text-fill-color: initial;
            text-shadow: none;
            font-weight: normal;
        }

        @keyframes tab-glow-anim {
            0% { filter: drop-shadow(0 0 2px var(--gold)); color: var(--gold); transform: translateY(-2px) scale(1.1); }
            100% { filter: drop-shadow(0 0 8px var(--vermilion)); color: var(--vermilion); transform: translateY(-4px) scale(1.2); }
        }

        .nav-btn.has-new:not(.active) .icon-gf {
            animation: tab-glow-anim 1.5s infinite alternate;
            color: var(--gold);
        }

        .nav-btn.has-new:not(.active)::after {
            content: '';
            position: absolute;
            top: 12px;
            right: 25%;
            width: 6px;
            height: 6px;
            background: var(--vermilion);
            border-radius: 50%;
            box-shadow: 0 0 4px var(--vermilion);
        }

        /* ===== 窄屏适配 ===== */
        @media screen and (max-width: 400px) {
            .nav-btn { font-size: 0.65rem; gap: 4px; } /* 恢复文字显示并调整间隙 */
            .nav-btn .icon-gf { font-size: 1.15rem; }
            .navbar { height: 64px; } /* 稍微加高导航栏，给名字留出空间 */
        }

        @media screen and (max-width: 480px) {
            .header { padding: 20px 16px 14px; }
            #ui-loc { font-size: 2rem; letter-spacing: 4px; margin-bottom: 8px; }
            #ui-time { font-size: 0.75rem; margin-bottom: 10px; }
            .content { padding: 10px 16px 50px; }
            .card { padding: 14px; }
            .radar-flex { flex-direction: column !important; align-items: center !important; }
            .radar-flex .data-grid { width: 100% !important; }
        }

        /* ===== PC端适配 ===== */
        @media screen and (min-width: 768px) {
            .wrapper {
                max-width: 900px;
                aspect-ratio: 9 / 14;
                border-radius: 8px;
                margin: 20px auto;
            }
            .content { padding: 20px 40px 80px; }
            .data-grid.g-3 { grid-template-columns: repeat(4, 1fr); }
            .m-card { width: 70%; height: 80%; margin: 0 auto; border-radius: 8px 8px 0 0; }
        }
        /* ===== 天机板块专属样式 ===== */
        .news-combat {
            background: linear-gradient(90deg, rgba(142,40,31,0.08), transparent);
            border-left: 3px solid var(--vermilion);
            border-radius: 0 4px 4px 0;
            padding: 14px 16px;
            margin-bottom: 24px;
            position: relative;
            overflow: hidden;
        }
        .news-combat::after {
            content: '战';
            position: absolute;
            right: 10px;
            bottom: -10px;
            font-size: 4rem;
            color: var(--vermilion);
            opacity: 0.04;
            font-family: var(--font-title);
            pointer-events: none;
        }
        .pet-plate {
            background: linear-gradient(135deg, rgba(255,255,255,0.7), rgba(255,255,255,0.3));
            border: 1px solid rgba(59,95,96,0.2);
            border-radius: 4px;
            padding: 14px;
            margin-bottom: 12px;
            display: flex;
            gap: 14px;
            align-items: center;
            position: relative;
            overflow: hidden;
            box-shadow: 0 2px 8px rgba(0,0,0,0.02);
        }
        .pet-plate::before {
            content: ''; position: absolute; top: 0; left: 0; width: 4px; height: 100%; background: var(--cyan);
        }
        .news-scroll-paper {
            background: linear-gradient(180deg, #fdfbf7 0%, #f4f1e9 5%, #f4f1e9 95%, #fdfbf7 100%);
            border-left: 1px solid rgba(179,139,77,0.4);
            border-right: 1px solid rgba(179,139,77,0.4);
            padding: 24px 20px;
            position: relative;
            box-shadow: 0 6px 20px rgba(0,0,0,0.06), inset 0 0 30px rgba(179,139,77,0.06);
            border-radius: 2px;
            margin-top: 10px;
        }
        .news-scroll-paper::before, .news-scroll-paper::after {
            content: ''; position: absolute; left: -4px; right: -4px; height: 10px;
            background: linear-gradient(90deg, #8a6d3b, #e0c98c, #8a6d3b);
            border-radius: 6px; box-shadow: 0 2px 6px rgba(0,0,0,0.3);
            z-index: 2;
        }
        .news-scroll-paper::before { top: -5px; }
        .news-scroll-paper::after { bottom: -5px; }
        .news-section { margin-bottom: 20px; padding-bottom: 16px; border-bottom: 1px dashed rgba(179,139,77,0.25); position: relative; z-index: 2; }
        .news-section:last-child { margin-bottom: 0; padding-bottom: 0; border-bottom: none; }
        .news-head { font-family: var(--font-title); font-size: 1.15rem; display: flex; align-items: center; gap: 8px; margin-bottom: 10px; letter-spacing: 1px; }

        /* ===== 减弱动画（低端设备/用户偏好） ===== */
        @media (prefers-reduced-motion: reduce) {
            .wrapper::before, .wrapper::after { animation: none !important; }
            .wrapper { animation: none !important; }
            .tier-dao-text { animation: none !important; }
            .zx-tier-5, .zx-tier-6, .zx-tier-7 { animation: none !important; }
            .tier-8, .tier-12, .tier-13 { animation: none !important; }
        }
/* ===== NPC 面板头部重构专属样式 (修复折行与溢出版) ===== */
        .npc-head-wrap {
            display: flex;
            align-items: center;
            gap: 16px;
            position: relative;
            box-sizing: border-box;
            width: 100%; /* 确保不超过父容器 */
        }
        .npc-head-avatar {
            width: 72px;
            height: 72px;
            flex-shrink: 0;
            display: flex;
            justify-content: center;
            align-items: center;
            font-family: var(--font-title);
            font-size: 2.2rem;
            border-radius: 8px;
            transform: rotate(45deg);
            position: relative;
            z-index: 2;
        }
        .npc-head-avatar span {
            transform: rotate(-45deg);
        }
        .npc-head-info {
            flex: 1;
            min-width: 0; /* 核心防御：强制 Flex 子项收缩，防止超长文字撑爆 UI */
            display: flex;
            flex-direction: column;
            justify-content: center;
        }
        .npc-name-box {
            display: flex;
            align-items: baseline;
            flex-wrap: wrap; /* 名字和道号过长时自动换行 */
            gap: 8px 12px;
            margin-bottom: 12px;
