    <script type="module">
        /* ===== 工具函数 ===== */

        /* 新增：数值单位格式化 (无->千->万->亿，保留4位有效数字) */
        var formatNum = function(num) {
            var n = parseFloat(num) || 0;
            if (n <= 0) return '0'; 
            if (n < 1000) return Math.floor(n).toString();
            if (n < 10000) return parseFloat((n / 1000).toPrecision(4)) + '千';
            if (n < 100000000) return parseFloat((n / 10000).toPrecision(4)) + '万';
            return parseFloat((n / 100000000).toPrecision(4)) + '亿';
        };

        var get = function(root, path) {
            try {
                if (!root) return undefined;
                if (path.indexOf('.') === -1 && path.indexOf('[') === -1) {
                    return root[path] !== undefined ? root[path] : undefined;
                }
                return path.split('.').reduce(function(obj, k) {
                    var m = k.match(/^(.+)\[(\d+)\]$/);
                    if (m && obj[m[1]]) return obj[m[1]][parseInt(m[2])];
                    return (obj && obj[k] !== undefined) ? obj[k] : undefined;
                }, root);
            } catch (e) { return undefined; }
        };

        var val = function(root, path, def) {
            if (def === undefined) def = '无';
            var v = get(root, path);
            if (v === undefined || v === null) return def;
            return (v === '' || v === 0) ? (v === 0 ? 0 : def) : v;
        };

        var realmDictionary = [
            /* T1 (0) */ ['感气', '聚气', '游魂', '凝血', '引气'],
            /* T2 (1) */ ['炼体', '淬骨', '怨灵', '淬魔'],
            /* T3 (2) */ ['筑基', '结妖', '厉鬼', '筑魔'],
            /* T4 (3) */ ['金丹', '小妖', '鬼将', '真魔'],
            /* T5 (4) */ ['元婴', '凝魄', '阴神', '魔胎'],
            /* T6 (5) */ ['化神', '大妖', '鬼王', '魔相'],
            /* T7 (6) */ ['合体', '妖王', '修罗', '魔尊'],
            /* T8 (7) */ ['大乘', '妖祖', '鬼尊', '大魔尊'],
            /* T9 (8) */ ['渡劫', '妖帝', '鬼帝', '魔帝', '帝境'],
            /* T10 (9) */['真仙'],
            /* T11 (10)*/['仙君'],
            /* T12 (11)*/['仙王'],
            /* T13 (12)*/['仙帝'],
            /* T14 (13)*/['道祖', '圣人']
        ];

        var getRealmTier = function(rStr) {
            if (!rStr) return 0;
            for (var i = realmDictionary.length - 1; i >= 0; i--) {
                for (var j = 0; j < realmDictionary[i].length; j++) {
                    if (rStr.includes(realmDictionary[i][j])) return i;
                }
            }
            return 0;
        };

        /* ===== 气运颜色（提取为顶层工具函数） ===== */
        var getLuckColor = function(luckStr) {
            if (!luckStr) return '#111418';
            if (luckStr.includes('橙') || luckStr.includes('琥')) return '#e67e22';
            if (luckStr.includes('粉') || luckStr.includes('桃') || luckStr.includes('魅') || luckStr.includes('胭')) return '#ec4899';
            if (luckStr.includes('金') || luckStr.includes('黄')) return '#c89b40';
            if (luckStr.includes('紫')) return '#7e57c2';
            if (luckStr.includes('红') || luckStr.includes('血') || luckStr.includes('凶')) return '#ab2b2b';
            if (luckStr.includes('蓝') || luckStr.includes('青')) return '#4a90e2';
            if (luckStr.includes('绿') || luckStr.includes('翠')) return '#5b8c5a';
            if (luckStr.includes('黑') || luckStr.includes('灰') || luckStr.includes('厄')) return '#4a4f52';
            return '#111418';
        };

        /* ===== 10档品阶色彩 ===== */
        var getTierStyle = function(tierStr) {
            var map = {
                '无': { c: '#aeb6bf', bg: 'rgba(174,182,191,0.05)', b: 'rgba(174,182,191,0.2)' },
                '凡': { c: '#7f8c8d', bg: 'rgba(127,140,141,0.05)', b: 'rgba(127,140,141,0.2)' },
                '黄': { c: '#5b8c5a', bg: 'rgba(91,140,90,0.05)', b: 'rgba(91,140,90,0.2)' },
                '玄': { c: '#4a6f70', bg: 'rgba(74,111,112,0.05)', b: 'rgba(74,111,112,0.2)' },
                '地': { c: '#6c537a', bg: 'rgba(108,83,122,0.05)', b: 'rgba(108,83,122,0.2)' },
                '天': { c: '#b38b4d', bg: 'rgba(179,139,77,0.05)', b: 'rgba(179,139,77,0.3)' },
                '仙': { c: '#c86f3b', bg: 'rgba(200,111,59,0.05)', b: 'rgba(200,111,59,0.3)' },
                '王': { c: '#8e281f', bg: 'rgba(142,40,31,0.05)', b: 'rgba(142,40,31,0.3)' },
                '帝': { c: '#111418', bg: 'linear-gradient(135deg, rgba(17,20,24,0.05), rgba(142,40,31,0.05))', b: 'rgba(17,20,24,0.4)', cls: 'tier-di-text' },
                '道': { c: '#b38b4d', bg: 'linear-gradient(135deg, rgba(179,139,77,0.05), rgba(92,67,102,0.05))', b: 'rgba(179,139,77,0.4)', cls: 'tier-dao-text' }
            };
            return map[tierStr] || map['无'];
        };

        var getTierDecor = function(tier, color) {
            var html = '';
            if (tier < 3) return '';
            if (tier >= 3 && tier <= 5) {
                html += '<div class="tier-decor" style="top:2px; left:2px; width:12px; height:12px; border-top:2px solid ' + color + '; border-left:2px solid ' + color + '; opacity:0.5;"></div>';
                html += '<div class="tier-decor" style="bottom:2px; right:2px; width:12px; height:12px; border-bottom:2px solid ' + color + '; border-right:2px solid ' + color + '; opacity:0.5;"></div>';
            } else if (tier >= 6 && tier <= 8) {
                html += '<div class="tier-decor" style="top:4px; left:4px; width:24px; height:24px; border-top:2px double ' + color + '; border-left:2px double ' + color + '; opacity:0.7;"></div>';
                html += '<div class="tier-decor" style="bottom:4px; right:4px; width:24px; height:24px; border-bottom:2px double ' + color + '; border-right:2px double ' + color + '; opacity:0.7;"></div>';
                html += '<div class="tier-decor" style="top:8px; right:8px; width:8px; height:8px; border-top:1px solid ' + color + '; border-right:1px solid ' + color + '; opacity:0.5;"></div>';
                html += '<div class="tier-decor" style="bottom:8px; left:8px; width:8px; height:8px; border-bottom:1px solid ' + color + '; border-left:1px solid ' + color + '; opacity:0.5;"></div>';
                var stamp = tier === 8 ? '⚡' : '☯';
                html += '<div class="tier-decor" style="right:15%; top:20%; font-size:4rem; color:' + color + '; opacity:0.06; font-family:var(--font-title); transform:rotate(-20deg);">' + stamp + '</div>';
            } else if (tier >= 9 && tier <= 10) {
                html += '<div class="tier-decor" style="inset:4px; border:1px solid ' + color + '; opacity:0.4; border-radius:2px;"></div>';
                html += '<div class="tier-decor" style="top:0; left:0; width:40px; height:40px; background:radial-gradient(circle at 0 0, ' + color + ' 10%, transparent 70%); opacity:0.3;"></div>';
                html += '<div class="tier-decor" style="bottom:0; right:0; width:40px; height:40px; background:radial-gradient(circle at 100% 100%, ' + color + ' 10%, transparent 70%); opacity:0.3;"></div>';
                html += '<div class="tier-decor" style="right:20px; top:50%; transform:translateY(-50%); font-size:2.5rem; color:' + color + '; opacity:0.15;">❀</div>';
            } else if (tier >= 11) {
                var emblem = tier === 13 ? '卍' : (tier === 12 ? '☸' : '♛');
                html += '<div class="tier-decor" style="inset:3px; border:1px solid ' + color + '; opacity:0.6;"></div>';
                html += '<div class="tier-decor" style="inset:6px; border:1px dashed ' + color + '; opacity:0.3;"></div>';
                html += '<div class="tier-decor" style="top:2px; left:2px; width:16px; height:16px; background:' + color + '; opacity:0.2; clip-path:polygon(0 0, 100% 0, 0 100%);"></div>';
                html += '<div class="tier-decor" style="bottom:2px; right:2px; width:16px; height:16px; background:' + color + '; opacity:0.2; clip-path:polygon(100% 100%, 100% 0, 0 100%);"></div>';
                html += '<div class="tier-decor" style="right:30px; top:50%; transform:translateY(-50%); font-size:4rem; color:' + color + '; opacity:0.2; text-shadow:0 0 10px ' + color + ';">' + emblem + '</div>';
            }
            return html;
        };

        var getZxTier = function(phaseStr, fragments) {
            var f = parseInt(fragments) || 0;
            if (f > 0) return Math.min(7, f);
            if (!phaseStr) return 0;
            var phases = ['未苏醒', '初显', '聚灵', '凝体', '化形', '御道', '至尊', '天道'];
            for (var i = phases.length - 1; i >= 0; i--) {
                if (phaseStr.includes(phases[i])) return i;
            }
            return 0;
        };

        var getZxDecor = function(tier) {
            var html = '';
            if (tier < 1) return '';
            var color = tier >= 6 ? 'var(--vermilion)' : (tier >= 3 ? 'var(--gold)' : 'var(--cyan)');
            if (tier >= 1 && tier <= 2) {
                html += '<div class="zx-decor" style="top:4px; left:4px; width:15px; height:15px; border-top:1px solid ' + color + '; border-left:1px solid ' + color + '; opacity:0.4;"></div>';
                html += '<div class="zx-decor" style="bottom:4px; right:4px; width:15px; height:15px; border-bottom:1px solid ' + color + '; border-right:1px solid ' + color + '; opacity:0.4;"></div>';
            } else if (tier >= 3 && tier <= 5) {
                html += '<div class="zx-decor" style="inset:6px; border:1px solid ' + color + '; opacity:0.3;"></div>';
                html += '<div class="zx-decor" style="top:0; left:50%; transform:translateX(-50%); font-size:2rem; color:' + color + '; opacity:0.1;">❁</div>';
                html += '<div class="zx-decor" style="bottom:0; left:50%; transform:translateX(-50%); font-size:2rem; color:' + color + '; opacity:0.1;">❁</div>';
                html += '<div class="zx-decor" style="top:10px; left:10px; width:30px; height:30px; border-top:2px double ' + color + '; border-left:2px double ' + color + '; opacity:0.5;"></div>';
                html += '<div class="zx-decor" style="bottom:10px; right:10px; width:30px; height:30px; border-bottom:2px double ' + color + '; border-right:2px double ' + color + '; opacity:0.5;"></div>';
                html += '<div class="zx-decor" style="right:10%; top:25%; font-size:6rem; color:' + color + '; opacity:0.04; font-family:var(--font-title); transform:rotate(15deg);">敕</div>';
            } else if (tier >= 6) {
                var godSymbol = tier === 7 ? '卍' : '☯';
                html += '<div class="zx-decor" style="inset:4px; border:2px solid ' + color + '; opacity:0.4;"></div>';
                html += '<div class="zx-decor" style="inset:10px; border:1px dashed var(--gold); opacity:0.5;"></div>';
                ['top:0;left:0', 'top:0;right:0', 'bottom:0;left:0', 'bottom:0;right:0'].forEach(function(pos) {
                    html += '<div class="zx-decor" style="' + pos + '; width:40px; height:40px; background:radial-gradient(circle at center, var(--gold) 0%, transparent 60%); opacity:0.2;"></div>';
                });
                html += '<div class="zx-decor" style="left:50%; top:45%; transform:translate(-50%, -50%); font-size:12rem; color:var(--gold); opacity:0.06; text-shadow: 0 0 20px var(--vermilion); pointer-events:none;">' + godSymbol + '</div>';
                html += '<div class="zx-decor" style="left:50%; top:45%; transform:translate(-50%, -50%); width:220px; height:220px; border:1px dashed var(--vermilion); border-radius:50%; opacity:0.1; pointer-events:none;"></div>';
            }
            return html;
        };

        var numToZh = function(numStr) {
            var num = parseInt(numStr);
            if (isNaN(num)) return numStr;
            if (num === 0) return '零';
            var chnNumChar = ["零", "一", "二", "三", "四", "五", "六", "七", "八", "九"];
            var chnUnitSection = ["", "万", "亿", "万亿"];
            var chnUnitChar = ["", "十", "百", "千"];
            var strIns = '', chnStr = '';
            var unitPos = 0, zero = true;
            while (num > 0) {
                var v = num % 10000;
                if (v === 0) {
                    if (!zero) { zero = true; chnStr = chnNumChar[0] + chnStr; }
                } else {
                    zero = false; strIns = '';
                    var tempV = v, p = 0;
                    while (tempV > 0) {
                        var t = tempV % 10;
                        if (t === 0) {
                            if (p !== 0 && !strIns.startsWith(chnNumChar[0])) strIns = chnNumChar[0] + strIns;
                        } else {
                            strIns = chnNumChar[t] + chnUnitChar[p] + strIns;
                        }
                        p++; tempV = Math.floor(tempV / 10);
                    }
                    chnStr = strIns + chnUnitSection[unitPos] + chnStr;
                }
                unitPos++; num = Math.floor(num / 10000);
            }
            if (chnStr.startsWith('一十')) chnStr = chnStr.substring(1);
            return chnStr;
        };

        var list = function(root, path) {
            var v = get(root, path);
            if (!v) return [];
            if (Array.isArray(v)) {
                var res = [];
                for (var i = 0, len = v.length; i < len; i++) {
                    var item = v[i];
                    if (item && typeof item === 'object' && !item.$meta && (item['名称'] || item['姓名'])) {
                        res.push(item);
                    }
                }
                return res;
            }
            if (typeof v === 'object') {
                var keys = Object.keys(v);
                var res2 = [];
                for (var j = 0, len2 = keys.length; j < len2; j++) {
                    var k = keys[j];
                    if (k === '$meta') continue;
                    var it = v[k];
                    if (typeof it === 'object' && it !== null) {
                        res2.push(Object.assign({}, it, { _key: k }));
                    }
                }
                return res2;
            }
            return [];
        };

        var bar = function(label, cur, max, color, min) {
            var c = parseFloat(cur) || 0;
            var m = parseFloat(max) || 100;
            var mn = parseFloat(min) || 0;
            var range = m - mn;
            var pct = Math.min(100, Math.max(0, range > 0 ? ((c - mn) / range) * 100 : 0));
            return '<div class="prog-wrap"><div class="prog-lbl">' + label + '</div><div class="prog-track"><div class="prog-bar" style="width:' + pct + '%; color:' + color + '"></div></div><div class="prog-val">' + formatNum(c) + '</div></div>';
        };

        var kv = function(k, v, color) {
            if (!color) color = '';
            return '<div class="kv-box"><div class="kv-k">' + k + '</div><div class="kv-v" style="color:' + color + '">' + v + '</div></div>';
        };

        var buildRadar = function(stats) {
            var size = 140, center = size / 2, radius = 50;
            var poly = '', labels = '', web = '';
            var angle = (Math.PI * 2) / stats.length;
            for (var level = 1; level <= 3; level++) {
                var pts = '', r = radius * (level / 3);
                for (var i = 0; i < stats.length; i++) {
                    var a = i * angle - Math.PI / 2;
                    pts += (center + r * Math.cos(a)) + ',' + (center + r * Math.sin(a)) + ' ';
                }
                web += '<polygon points="' + pts + '" fill="' + (level === 3 ? 'rgba(179,139,77,0.03)' : 'none') + '" stroke="rgba(179,139,77,0.2)" stroke-width="0.5"/>';
            }
            for (var i2 = 0; i2 < stats.length; i2++) {
                var a2 = i2 * angle - Math.PI / 2;
                web += '<line x1="' + center + '" y1="' + center + '" x2="' + (center + radius * Math.cos(a2)) + '" y2="' + (center + radius * Math.sin(a2)) + '" stroke="rgba(179,139,77,0.2)" stroke-width="0.5"/>';
