            }
            return '<svg width="' + size + '" height="' + size + '" viewBox="0 0 ' + size + ' ' + size + '" style="filter: drop-shadow(0 0 10px rgba(179,139,77,0.3));">' + web + '<polygon points="' + poly + '" fill="rgba(179,139,77,0.35)" stroke="var(--gold)" stroke-width="1.5" stroke-linejoin="round"/><circle cx="' + center + '" cy="' + center + '" r="2" fill="var(--gold)"/>' + labels + '</svg>';
