        var checkDataUpdates = function(oldD, newD) {
            if (!oldD || Object.keys(oldD).length === 0) return;
            var tabsToCheck = {
                'status': ['主角.境界', '主角.当前命', '主角.战力', '主角.功法'],
                'fashen': ['主角.装备', '主角.肉体详情', '主角.敏感度'],
                'sect': ['宗门'],
                'bag': ['行囊', '资产'],
