                'news': ['战斗', '灵兽栏', '宅仙报'],
                'zhaixian': ['小宅仙面板']
            };
            var $activeBtn = $('.nav-btn.active');
            var activeTabKey = null;
            if ($activeBtn.length) {
                var onclickStr = $activeBtn.attr('onclick') || '';
                var match = onclickStr.match(/'(.*)'/);
                if (match) activeTabKey = match[1];
            }
            for (var tabKey in tabsToCheck) {
                if (tabKey === activeTabKey) continue;
                var changed = false;
                for (var pi = 0; pi < tabsToCheck[tabKey].length; pi++) {
                    var path = tabsToCheck[tabKey][pi];
                    var oldStr = JSON.stringify(get(oldD, path) || {});
                    var newStr = JSON.stringify(get(newD, path) || {});
                    if (oldStr !== newStr) { changed = true; break; }
                }
                if (changed) {
                    $('.nav-btn[onclick="Tab(\'' + tabKey + '\')"]').addClass('has-new');
                }
            }
        };

        window.Tab = function(key) {
            $('.nav-btn').removeClass('active');
            var idx = ['status', 'fashen', 'sect', 'bag', 'social', 'news', 'zhaixian'].indexOf(key);
            if (idx >= 0) {
                var $btn = $('.nav-btn').eq(idx);
                $btn.addClass('active').removeClass('has-new');
            }
            /* 智能缓存：只有数据源变化时才清缓存 */
            if (window._globalDataRef !== lastData) {
                viewCache = {};
                window._globalDataRef = lastData;
            }
            if (!viewCache[key]) {
                viewCache[key] = UI[key] ? UI[key](lastData) : '<div style="padding:50px;text-align:center;color:var(--sub)">天道演算中...</div>';
            }
            smoothRender(viewCache[key]);
