        window.closeModal = function() {
            var $modal = $('#modal');
            $modal.removeClass('show');
            setTimeout(function() {
                if (!$modal.hasClass('show')) {
                    $('#m-content').html('');
                }
            }, 400);
        };

        /* ===== 数据刷新 ===== */
        window.populateCharacterData = function() {
            var all_variables = getAllVariables();
            var d = _.get(all_variables, 'stat_data', {});
            checkDataUpdates(lastData, d);
            lastData = JSON.parse(JSON.stringify(d));
            /* 不再无脑清缓存，由Tab和SilentUpdate通过_globalDataRef判断 */
            UI.header(d);
            var $active = $('.nav-btn.active');
            var key = 'status';
            if ($active.length) {
                var onclickStr = $active.attr('onclick') || '';
                var match = onclickStr.match(/'(.*)'/);
                if (match) key = match[1];
            }
            SilentUpdate(key);
        };

        /* ===== 初始化 ===== */
        async function init() {
            /* 【新增】：在等待框架加载及渲染前，先从数据库恢复特别关注列表 */
            let savedFocus = await loadFromDB('focusedNPCs');
            if (savedFocus) {
                window.socialState.focusedNPCs = savedFocus;
            }

            await waitGlobalInitialized('Mvu');

            /* NPC卡片点击委托 */
            $('#view').on('click', '.npc-clickable', function() {
                var idx = $(this).attr('data-idx');
                if (idx !== null && idx !== undefined) openModal(parseInt(idx));
            });

            /* 弹窗关闭 */
            $('#modal').on('click', function(e) {
                if (e.target === this) closeModal();
            });
            $('#m-close-btn').on('click', function() { closeModal(); });

            /* 弹窗拖拽关闭 */
            var dragStartY = 0, dragCurrentY = 0, isDraggingCard = false;
            var $mCardDrag = $('#m-card');

            $mCardDrag.on('touchstart', function(e) {
                dragStartY = e.originalEvent.touches[0].clientY;
                isDraggingCard = false;
                $mCardDrag.css('transition', 'none');
            });

            $mCardDrag.on('touchmove', function(e) {
                var mBodyDom = document.getElementById('m-content');
                var currentY = e.originalEvent.touches[0].clientY;
                if (mBodyDom && mBodyDom.scrollTop <= 0) {
                    if (!isDraggingCard && currentY > dragStartY) {
                        isDraggingCard = true;
                        dragStartY = currentY;
                    }
                    if (isDraggingCard) {
                        var delta = currentY - dragStartY;
                        if (delta > 0) {
                            if (e.originalEvent.cancelable) e.originalEvent.preventDefault();
                            dragCurrentY = delta;
                            $mCardDrag.css('transform', 'translateY(' + delta + 'px)');
                        }
                    }
                } else {
                    isDraggingCard = false;
                    dragStartY = currentY;
                }
            });

            $mCardDrag.on('touchend', function() {
                if (!isDraggingCard) return;
                isDraggingCard = false;
                $mCardDrag.css('transition', 'transform 0.4s cubic-bezier(0.16, 1, 0.3, 1), opacity 0.4s ease');
                if (dragCurrentY > 120) closeModal();
                else $mCardDrag.css('transform', '');
                dragCurrentY = 0;
            });

            /* 首次渲染 */
            populateCharacterData();
            Tab('status');

            /* 持续监听 */
            eventOn(Mvu.events.VARIABLE_UPDATE_ENDED, function() {
                populateCharacterData();
            });
        }

        $(errorCatched(init));
    </script>
</body>
