import { registerMvuSchema } from 'https://testingcf.jsdelivr.net/gh/StageDog/tavern_resource/dist/util/mvu_zod.js';

// ===== 工具函数：处理 AI 偶发输出 null/undefined 的字符串字段 =====
const nullableStr = (def) =>
  z.string().nullable().transform(v => v ?? def).prefault(def);

// ===== 工具函数：钳位整数 =====
const clampNum = (min, max, def) =>
  z.coerce.number().transform(v => _.clamp(v, min, max)).prefault(def);

// ===== 装备/物品的品质枚举（10 档铁律） =====
const 品质枚举 = z.enum(['无', '凡', '黄', '玄', '地', '天', '仙', '王', '帝', '道']);
// ===== 功法/神通的品阶枚举（8 档铁律） =====
const 品阶枚举 = z.enum(['黄', '玄', '地', '天', '仙', '王', '帝', '道']);

// ===== 功法子对象 =====
const 功法Schema = z.object({
  名称: z.string().prefault('未知功法'),
  品阶: 品阶枚举.prefault('黄'),
  修炼层数: z.string().prefault('第一层'),
  效果: z.string().prefault('无'),
}).prefault({});

// ===== 神通子对象 =====
const 神通Schema = z.object({
  名称: z.string().prefault('未知神通'),
  品阶: 品阶枚举.prefault('黄'),
  熟练度: z.string().prefault('入门'),
  效果: z.string().prefault('无'),
}).prefault({});

// ===== 物品分类枚举（13 类铁律） =====
const 分类枚举 = z.enum([
  '武器', '防具', '饰品', '衣物', '丹药', '符箓', '灵植',
  '功法', '秘籍', '法器', '材料', '杂物', '任务物品'
]);

// ===== 装备槽位 schema（已装备由名称自动推导）=====
const 装备槽 = z.object({
  名称: z.string().prefault('无'),
  品质: 品质枚举.prefault('无'),
  描述: z.string().prefault('无'),
  作用: z.string().prefault('无'),
  已装备: z.boolean().prefault(false),
}).prefault({});

// ===== 敏感度子对象 =====
const 敏感度Schema = z.object({
  口: z.coerce.number().prefault(10),
  胸: z.coerce.number().prefault(10),
  前穴: z.coerce.number().prefault(10),
  后穴: z.coerce.number().prefault(10),
  阳具: z.coerce.number().prefault(10),
  全身: z.coerce.number().prefault(10),
}).prefault({});

// ===== 肉体详情子对象 =====
const 肉体详情Schema = z.object({
  胸部: nullableStr('无奇'),
  屁眼: nullableStr('紧致'),
  小穴: nullableStr('未经人事'),
  阳具: nullableStr('无'),
  囊袋: nullableStr('无'),
  前列腺: nullableStr('无'),
  足部: nullableStr('普通'),
  嘴部: nullableStr('普通'),
}).prefault({});

// ============================================
// 主 Schema
// ============================================
export const Schema = z.object({

  世界: z.object({
    时间: z.string().prefault('复苏历元年'),
    地点: z.string().prefault('大荒边界'),
    世界动态: z.string().prefault(''),
    灵气浓度: z.string().prefault('稀薄'),
    天气: z.string().prefault('晴朗'),
    天道压制: clampNum(0, 100, 0),
  }).prefault({}),

  资产: z.object({
    极品灵石: z.coerce.number().prefault(0),
    上品灵石: z.coerce.number().prefault(0),
    中品灵石: z.coerce.number().prefault(0),
    下品灵石: z.coerce.number().prefault(0),
    黄金: z.coerce.number().prefault(0),
    白银: z.coerce.number().prefault(0),
    铜钱: z.coerce.number().prefault(0),
  }).prefault({}),

  主角: z.object({
    姓名: z.string().prefault('无名氏'),
    年龄: z.coerce.number().prefault(18),
    境界: z.string().prefault('凡人'),
    灵根: z.string().prefault('无'),
    种族: z.string().prefault('人族'),
    体质: z.string().prefault('凡体'),
    气运: nullableStr('白'),                    // ← 防报错：与 NPC 气运一致
    名声: z.string().prefault('默默无闻'),
    阵营: z.string().prefault('中立'),
    魅力: z.coerce.number().prefault(50),
    神识: z.coerce.number().prefault(10),
    战力: z.coerce.number().prefault(10),
    道心: clampNum(0, 100, 100),
    悟: clampNum(0, 100, 0),
    当前命: z.coerce.number().prefault(100),
    命: z.coerce.number().prefault(100),
    当前灵: z.coerce.number().prefault(100),
    灵: z.coerce.number().prefault(100),
    成就勋章: z.array(z.string()).prefault([]),
    生理: z.object({
      欲望槽: clampNum(0, 100, 0),
      体香: z.string().prefault('无'),
    }).prefault({}),
    外貌: z.string().prefault('普通'),
    装备: z.object({
      固定部位: z.record(
        z.enum(['主手', '副手', '头部', '身体', '手部', '腿部', '足部']),
