        z.string().describe('饰品键名（如「护心玉佩」）'),
        装备槽
      ).prefault({}),
    })
    .prefault({})
    .transform(data => ({
      固定部位: _.mapValues(data.固定部位, item => ({
        ...item,
        已装备: item.名称 !== '无',          // 名称非"无"即已装备，铁律
      })),
      饰品: _.mapValues(data.饰品, item => ({
        ...item,
        已装备: true,                         // 饰品在装备区即已装备
      })),
    })),
    肉体详情: 肉体详情Schema,
    三围: z.object({
      胸围: z.coerce.number().prefault(0),
      腰围: z.coerce.number().prefault(0),
      臀围: z.coerce.number().prefault(0),
    }).prefault({}),
    身高: z.coerce.number().prefault(0),
    体重: z.coerce.number().prefault(0),
    敏感度: 敏感度Schema,
    技艺: z.object({
      炼丹: z.string().prefault('未入门'),
      炼器: z.string().prefault('未入门'),
      符箓: z.string().prefault('未入门'),
      阵法: z.string().prefault('未入门'),
      御兽: z.string().prefault('未入门'),
    }).prefault({}),
    功法: z.record(
      z.string().describe('功法键名'),
      功法Schema
    ).prefault({}),
    神通: z.record(
      z.string().describe('神通键名'),
      神通Schema
    ).prefault({}),
  }).prefault({}),

  // ===== 宗门：从 z.any() 升级为完整结构（与变量更新规则一致） =====
  宗门: z.record(
    z.string().describe('宗门键名'),
    z.object({
      名称: z.string().prefault('未知宗门'),
      等级: z.coerce.number().prefault(1),
      阵营: z.string().prefault('中立'),
      宗旨: z.string().prefault('无'),
      声望: z.coerce.number().prefault(0),
      风气: z.string().prefault('普通'),
