const MODE_DEFS = [
  { className: 'resize-ext-mode',    label: '扩展条目自适应高度',    defaultOn: true },
  { className: 'resize-prompt-mode', label: '提示词管理器自适应高度', defaultOn: true },
  { className: 'resize-wb-mode',     label: '世界书文本框自适应高度', defaultOn: true },
  { className: 'resize-regex-mode',  label: '正则条目自适应高度',    defaultOn: true },
  { className: 'resize-script-mode', label: '脚本条目自适应高度',    defaultOn: true },
];

const topDocument = window.parent.document;
const topBodyNode = topDocument.body;

// ===== 模块级缓存，避免重复查询 =====
let cachedSettings = null;
let panelEl = null;
let overlayEl = null;
let mainObserver = null;

// ===== 缓存在脚本生命周期内，频繁访问不再重复读取 =====
function loadSettings() {
  try {
    const vars = getVariables({ type: 'script' });
    return vars || {};
  } catch (e) {
    console.warn('[界面调整] 读取脚本变量失败，用默认设置', e);
    return {};
  }
}

function saveSettingsToVar(settings) {
  try {
    replaceVariables(settings, { type: 'script' });
  } catch (e) {
    console.warn('[界面调整] 保存脚本变量失败', e);
  }
  cachedSettings = settings;
}

function getEffectiveSettings() {
  if (cachedSettings) return cachedSettings;
  const saved = loadSettings();
  const result = {};
  for (const def of MODE_DEFS) {
    if (typeof saved[def.className] === 'boolean') {
      result[def.className] = saved[def.className];
    } else {
      result[def.className] = def.defaultOn;
    }
  }
  cachedSettings = result;
  return result;
}

function applyClassNames(settings) {
  for (const def of MODE_DEFS) {
    if (settings[def.className]) {
      topBodyNode.classList.add(def.className);
    } else {
      topBodyNode.classList.remove(def.className);
    }
  }
}

// ===== 注入 CSS =====
const existingStyle = topDocument.getElementById(CSS_ELEMENT_ID);
if (existingStyle) {
  existingStyle.textContent = LAYOUT_STYLESHEET;
} else {
  const newStyleTag = topDocument.createElement('style');
  newStyleTag.id = CSS_ELEMENT_ID;
  newStyleTag.textContent = LAYOUT_STYLESHEET;
  topDocument.head.appendChild(newStyleTag);
}

// ===== 初始化：读取设置 + 应用 CSS 类（脚本生命周期内仅执行一次）=====
const currentSettings = getEffectiveSettings();
applyClassNames(currentSettings);
console.log('[界面调整] 已根据设置应用类名:', currentSettings);

// ===== 设置面板 =====
// 初始化时创建一次，后续只切换可见性，避免重建 DOM
function createPanel() {
  topDocument.getElementById(PANEL_ID)?.remove();
  topDocument.getElementById(`${PANEL_ID}-overlay`)?.remove();

  overlayEl = topDocument.createElement('div');
  overlayEl.id = `${PANEL_ID}-overlay`;
  topDocument.body.appendChild(overlayEl);

  panelEl = topDocument.createElement('div');
  panelEl.id = PANEL_ID;

  const title = topDocument.createElement('div');
  title.className = 'panel-title';
  title.textContent = '自适应条目高度设置';
  panelEl.appendChild(title);

  for (const def of MODE_DEFS) {
    const item = topDocument.createElement('div');
    item.className = 'panel-item';

    const label = topDocument.createElement('label');
    label.textContent = def.label;
    label.setAttribute('for', `chk-${def.className}`);

    const checkbox = topDocument.createElement('input');
    checkbox.type = 'checkbox';
    checkbox.id = `chk-${def.className}`;
    checkbox.checked = currentSettings[def.className];

    checkbox.addEventListener('change', () => {
      currentSettings[def.className] = checkbox.checked;
      applyClassNames(currentSettings);
      saveSettingsToVar(currentSettings);
      console.log(`[界面调整] ${def.label} ${checkbox.checked ? '开启' : '关闭'}`);
    });

    item.appendChild(label);
    item.appendChild(checkbox);
    panelEl.appendChild(item);
  }

  const closeBtn = topDocument.createElement('button');
  closeBtn.className = 'panel-close-btn';
  closeBtn.textContent = '关闭';
  closeBtn.addEventListener('click', closePanel);
  panelEl.appendChild(closeBtn);

  topDocument.body.appendChild(panelEl);
  overlayEl.addEventListener('click', closePanel);
}

function openPanel() {
  if (!panelEl || !overlayEl) return;
  // 打开前同步 checkbox 状态
  for (const def of MODE_DEFS) {
    const chk = topDocument.getElementById(`chk-${def.className}`);
    if (chk) chk.checked = currentSettings[def.className];
  }
  panelEl.classList.add('panel-visible');
  overlayEl.classList.add('panel-visible');
}

function closePanel() {
  if (panelEl) panelEl.classList.remove('panel-visible');
  if (overlayEl) overlayEl.classList.remove('panel-visible');
}

createPanel();

// ===== 脚本按钮 =====
eventClearEvent(getButtonEvent(BTN_NAME));
replaceScriptButtons([{ name: BTN_NAME, visible: true }]);
eventOn(getButtonEvent(BTN_NAME), openPanel);

console.log('[界面调整] 脚本按钮和设置面板已创建');

// ===== 优化：单个 MutationObserver 统一检测所有目标元素 =====
// 原版每个 selector 单独创建 observer，现在合并为一个，找到所有目标后立即 disconnect
const TARGET_SELECTORS = [
  { selector: '.world_entry_form textarea.text_pole',     modeClass: 'resize-wb-mode'     },
  { selector: '.extension_block',                         modeClass: 'resize-ext-mode'    },
  { selector: '.completion_prompt_manager_prompt',       modeClass: 'resize-prompt-mode' },
  { selector: '.regex-script-label',                    modeClass: 'resize-regex-mode'  },
];

let pendingSelectors = [...TARGET_SELECTORS];
const debounceState = { id: null, cbs: [] };

function flushCallbacks() {
  const cbs = debounceState.cbs.splice(0);
  debounceState.id = null;
  cbs.forEach(cb => cb());
}

mainObserver = new MutationObserver(() => {
  if (pendingSelectors.length === 0) {
    mainObserver.disconnect();
    return;
  }
  const newCallbacks = [];
  pendingSelectors = pendingSelectors.filter(({ selector }) => {
    const found = topDocument.querySelectorAll(selector);
    if (found.length > 0) {
      newCallbacks.push(() => {
        console.log(`[界面调整] 检测到 ${found.length} 个目标: ${selector}`);
      });
      return false;
    }
    return true;
  });
  if (newCallbacks.length > 0) {
    debounceState.cbs.push(...newCallbacks);
    if (!debounceState.id) {
      debounceState.id = setTimeout(flushCallbacks, 200);
    }
  }
});

mainObserver.observe(topBodyNode, { childList: true, subtree: true });

// ===== 清理 =====
$(window).on('pagehide', () => {
  eventClearEvent(getButtonEvent(BTN_NAME));
  topDocument.getElementById(CSS_ELEMENT_ID)?.remove();
  topDocument.getElementById(PANEL_ID)?.remove();
  topDocument.getElementById(`${PANEL_ID}-overlay`)?.remove();

  topBodyNode.classList.remove(...MODE_DEFS.map(d => d.className));

  if (mainObserver) {
    mainObserver.disconnect();
    mainObserver = null;
  }
  if (debounceState.id) clearTimeout(debounceState.id);

  console.log('[界面调整] 页面关闭，已清理所有内容');
});

console.log('[界面调整] 脚本全部执行完了');
